comms.text:
@1 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@2 מַלֵל עִם כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן קַדִישִׁין תְּהוֹן אֲרֵי קַדִישׁ אֲנָא יְיָ אֱלָהָכוֹן:
@3 גְבַר מִן אִמֵהּ וּמִן אֲבוּהִי תְּהוֹן דָחֲלִין וְיָת יוֹמֵי שַׁבַּיָא דִילִי תִּטְרוּן אֲנָא יְיָ אֱלָהָכוֹן:
@4 לָא תִתְפְּנוּן בָּתַר טַעֲוָן וְדַחֲלָן דְמַתְּכָא לָא תַעְבְּדוּן לְכוֹן אֲנָא יְיָ אֱלָהָכוֹן:
@5 וַאֲרֵי תִכְסוּן נִכְסַת קוּדְשַׁיָא קֳדָם יְיָ לְרַעֲוָא לְכוֹן תִּכְסֻנֵהּ:
@6 בְּיוֹמָא דְיִתְנְכֵס יִתְאֲכֵל וּבְיוֹמָא דְבַתְרוֹהִי וּדְאִשְׁתָּאַר עַד יוֹמָא תְלִיתָאָה בְּנוּרָא יִתּוֹקָד:
@7 וְאִם אִתְאֲכָלָא יִתְאֲכֵל בְּיוֹמָא תְלִיתָאָה מְרָחַק הוּא לָא יְהֵי לְרַעַוָא:
@8 וּדְיֵיכְלִנֵהּ חוֹבֵהּ יְקַבֵּל אֲרֵי יָת קוּדְשָׁא דַיְיָ אַחֵל וְיִשְׁתֵּיצֵי אֲנָשָׁא הַהוּא מֵעַמֵהּ:
@9 וּבְמֶחְצָדְכוֹן יָת חֲצָדָא דְאַרְעֲכוֹן לָא תְשֵׁיצֵי פָּאתָא דְחַקְלָךְ לְמֶחְצָד וּלְקָטָא דַחֲצָדָךְ לָא תְלַקֵט:
@10 וְכַרְמָךְ לָא תְעַלֵל וְנִתְרָא דְכַרְמָךְ לָא תְלַקֵט לְעַנְיֵי וּלְגִיוֹרֵי תִּשְׁבּוֹק יָתְהוֹן אֲנָא יְיָ אֱלָהָכוֹן:
@11 לָא תִּגְנְבוּן וְלָא תְכַדְבוּן וְלָא תְשַׁקְרוּן אֱנַשׁ בְּחַבְרֵהּ:
@12 וְלָא תִשָׁבְעוּן בִּשְׁמִי לְשִׁקְרָא וְתַחֵל יָת שְׁמָא דֶאֱלָהָךְ אֲנָא יְיָ:
@13 לָא תַעֲשׁוֹק יָת חַבְרָךְ וְלָא תְאַנֵס לָא תְבִית אַגְרָא דַאֲגִירָא לְוָתָךְ עַד צַפְרָא:
@14 לָא תְלוּטּ דְלָא שָׁמַע וְקֳדָם דְלָא חָזֵי לָא תְשִׂים תַּקְלָא וְתִדְחַל מֵאֱלָהָךְ אֲנָא יְיָ:
@15 לָא תַעְבְּדוּן שְׁקַר בְּדִינָא לָא תִסַב אַפֵּי מַסְכֵּנָא וְלָא תֶהְדַר אַפֵּי רַבָּא בְּקוּשְׁטָא תְּדִינֵהּ לְחַבְרָךְ:
@16 לָא תֵיכוּל קוּרְצִין בְּעַמָךְ לָא תְקוּם עַל דְמָא דְחַבְרָךְ אֲנָא יְיָ:
@17 לָא תִשְׂנֵי יָת אֲחוּךְ בְּלִבָּךְ אוֹכָחָא תוֹכַח יָת חַבְרָךְ וְלָא תְקַבֵּל עַל דִי לֵהּ חוֹבָא:
@18 לָא תִקוֹם וְלָא תִטַר דְבָבוּ לִבְנֵי עַמָךְ וּתְרַחֵם לְחַבְרָךְ כְּוָתָךְ אֲנָא יְיָ:
@19 יָת קְיָמַי תִּטְרוּן בְּעִירָךְ לָא תַרְכֵּב עֵרוּבִין חַקְלָךְ לָא תִזְרַע עֵרוּבִין וּלְבוּשׁ עֵרוּבִין שַׁעַטְנֵזָא לָא יִסַק עֲלָךְ:
@20 וּגְבַר אֲרֵי יִשְׁכּוּב עִם אִתְּתָא שִׁכְבַת זַרְעָא וְהִיא אַמְתָא אֲחִידָא לִגְבַר וְאִתְפְּרָקָא לָא אִתְפְּרִיקַת בְּכַסְפָּא אוֹ חֵרוּתָא לָא אִתְיְהִיבַת לַהּ בִּשְׁטָר בִּקֻּרְתָּא תְהֵי לָא יוּמְתוּן אֲרֵי לָא אִתְחָרָרַת:
@21 וְיַיְתִי יָת אַשְׁמֵהּ קֳדָם יְיָ לִתְרַע מַשְׁכַּן זִמְנָא דְכַר לַאֲשָׁמָא:
@22 וִיכַפֵּר עֲלוֹהִי כַּהֲנָא בְּדִכְרָא דַאֲשָׁמָא קֳדָם יְיָ עַל חוֹבְתֵהּ דִי חָב וְיִשְׁתְּבֵק לֵהּ מְחוֹבְתֵהּ דִי חַב:
@23 וַאֲרֵי תֵעֲלוּן לְאַרְעָא וְתִצְבוּן כָּל אִלָן דְמֵיכַל וּתְרַחֲקוּן רָחָקָא יַת אִבֵּהּ תְּלַת שְׁנִין יְהֵי לְכוֹן מְרָחָק לַאֲבָדָא לָא יִתְאֲכֵל:
@24 וּבְשַׁתָּא רְבִיעֵתָא יְהֵי כָּל אִבֵּהּ קֹדֶשׁ תּוּשְׁבְּחָן קֳדָם יְיָ:
@25 וּבְשַׁתָּא חֲמִישֵׁתָא תֵּיכְלוּן יָת אִבֵּהּ לְאוֹסָפָא לְכוֹן עֲלַלְתֵּהּ אֲנָא יְיָ אֱלָהָכוֹן:
@26 לָא תֵיכְלוּן עַל דְמָא לָא תְנַחֲשׁוּן וְלָא תְעוֹנוּן:
@27 לָא תַקְפוּן פָּאתָא דְרֵישְׁכוֹן וְלָא תְחַבֵּל יָת פָּאתָא דְדִקְנָךְ:
@28 וְחִבּוּל עַל מִית לָא תִתְּנוּן בְּבִסְרְכוֹן וְרוּשְׁמִין חֲרִיתִין לָא תִתְּנוּן בְכוֹן אֲנָא יְיָ:
@29 לָא תַחֵל יָת בְּרַתָּךְ לְאַטְעֲיוּתַהּ וְלָא תִטְעֵי אַרְעָא וְתִתְמְלֵי אַרְעָא עֵצַת חִטְאִין:
@30 יָת יוֹמֵי שַׁבַּיָא דִילִי תִּטְרוּן וּלְבֵית מַקְדְשִׁי תְּהוֹן דָחֲלִין אֲנָא יְיָ:
@31 לָא תִתְפְּנוּן בָּתַר בִּדִין וּדְכוּרוּ לָא תִתְבְּעוּן לְאִסְתָּאָבָא בְהוֹן אֲנָא יְיָ אֱלָהָכוֹן:
@32 מִן קֳדָם דְסַבַּר בְּאוֹרַיְתָא תְּקוּם וּתְהַדַר אַפֵּי סָבָא וְתִדְחַל מֵאֳלָהָךְ אֲנָא יְיָ:
@33 וַאֲרֵי יִתְגַיַר עִמָךְ גִיוֹרָא בְּאַרְעֲכוֹן לָא תוֹנוּן יָתֵהּ:
@34 כְּיַצִיבָא מִנְכוֹן יְהֵי לְכוֹן גִיוֹרָא דְיִתְגַיַר בֵּינֵיכוֹן וּתְרַחֵם לֵהּ כְּוָתָךְ אֲרֵי דַיָרִין הֲוֵיתוּן בְּאַרְעָא דְמִצְרָיִם אֲנָא יְיָ אֱלָהָכוֹן:
@35 לָא תַעְבְּדוּן שְׁקַר בְּדִין בִּמְשַׁחְתָּא בְּמַתְקְלָא וּבִמְכִלְתָּא:
@36 מֹאזְנָוָן דִקְשׁוֹט מַתְקְלָן דִקְשׁוֹט מְכִילָן דִקְשׁוֹט וְהִינִין דִקְשׁוֹט יְהוֹן לְכוֹן אֲנָא יְיָ אֱלָהָכוֹן דִי אֲפֵּקִית יָתְכוֹן מֵאַרְעָא דְמִצְרָיִם:
@37 וְתִטְרוּן יָת כָּל קְיָמַי וְיָת כָּל דִינַי וְתַעְבְּדוּן יָתְהוֹן אֲנָא יְיָ:
@38 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@39 וְלִבְנֵי יִשְׂרָאֵל תֵּימַר גְבַר גְבַר מִבְּנֵי יִשְׂרָאֵל וּמִן גִיוֹרָא דְיִתְגַיְרוּן בְּיִשְׂרָאֵל דִי יִתֵּן מִזַרְעֵהּ לְמוֹלֶךְ אִתְקְטָלָא יִתְקְטֵל עַמָא בֵית יִשְׂרָאֵל יִרְגְמֻנֵהּ בְּאַבְנָא:
@40 וַאֲנָא אֶתֵּן יָת רוּגְזִי בְגַבְרָא הַּהוּא וְאֱשֵׁיצֵי יָתֵהּ מִגוֹ עַמֵהּ אֲרֵי מִזַרְעֵהּ יְהַב לְמוֹלֶךְ בְּדִיל לְסָאָבָא יָת מַקְדְשִׁי וּלְאַחַלָא יָת שְׁמָא דְקוּדְשִׁי:
@41 וְאִם מִכְבַּשׁ יִכְבְּשׁוּן עַמָא בֵית יִשְׂרָאֵל יָת עֵינֵיהוֹן מִן גַבְרָא הַהוּא בִּדְיָהֵב מִזַרְעֵהּ לְמוֹלֶךְ בְּדִיל דְלָא לְקַטָלָא יָתֵהּ:
@42 וֶאֱשַׁוֵי אֲנָא יָת רוּגְזִי בְגַבְרָא הַהוּא וּבִסְעָדוֹהִי וֶאֱשֵׁיצֵי יָתֵהּ וְיָת כָּל דְטָעָן בַּתְרוֹהִי לְמִטְעֵי בָּתַר מוֹלֶךְ מִגוֹ עַמְהוֹן:
@43 וֶאֱנַשׁ דִי יִתְפְּנֵי בָּתַר בִּדִין וּדְכוּרוּ לְמִטְעֵי בַתְרֵיהוֹן וְאֶתֵּן יָת רוּגְזִי בַּאֲנָשָׁא הַהִיא וֶאֱשֵׁיצֵי יָתֵהּ מִגוֹ עַמֵהּ:
@44 וְתִתְקַדְשׁוּן וּתְהוֹן קַדִישִׁין אֲרֵי אֲנָא יְיָ אֱלָהָכוֹן:
@45 וְתִטְּרוּן יָת קְיָמַי וְתַעְבְּדוּן יָתְהוֹן אֲנָא:ייָ מַקְדִשְׁכוֹן:
@46 אֲרֵי גְבַר גְבַר דִי יְלוּט יָת אֲבוּהִי וְיָת אִמֵהּ אִתְקְטָּלָא יִתְקְטֵל אֲבוּהִי וְאִמֵהּ לַטּ קְטָלָא חַיָב:
@47 וּגְבַר דִי יְגוּף יָת אִתַּת גְבַר דִי יְגוּף יָת אִתַּת חַבְרֵהּ אִתְקְטָלָא יִתְקְטֵל גַיָפָא וְגַיַפְתָּא:
@48 וּגְבַר דִי יִשְׁכּוּב עִם אִתַּת אֲבוּהִי עֶרְיְתָא דַאֲבוּהִי גַלִי אִתְקַטָלָא יִתְקַטְלוּן תַּרְוֵיהוֹן קְטָלָא חַיָבִין:
@49 וּגְבַר דִי יִשְׁכּוּב יָת כַּלָתֵהּ אִתְקְטָלָא יִתְקַטְלוּן תַּרְוֵיהוֹן תִּבְלָא עֲבָדוּ קְטָלָא חַיָבִין:
@50 וּגְבַר דִי יִשְׁכּוּב יָת דְכוּרָא מִשְׁכְּבֵי אִתְּתָא תּוֹעֶבְתָּא עֲבָדוּ תַּרְוֵיהוֹן אִתְקְטָלָא יִתְקַטְלוּן קְטָלָא חַיָבִין:
@51 וּגְבַר דִי יִסַב יָת אִתְּתָא וְיָת אִמַהּ עֵצַת חִטְאִין הִיא בְּנוּרָא יוֹקְדוּן יָתֵהּ וְיָתְהֶן וְלָא תְהֵי עֵצַת חִטְאִין בֵּינֵיכוֹן:
@52 וּגְבַר דִי יִתֵּן שְׁכָבְתֵּהּ בִּבְעִירָא אִתְקְטָלָא יִתְקְטֵל וְיָת בְּעִירָא תִּקְטְלוּן:
@53 וְאִתְּתָא דִי תִקְרַב לְכָל בְּעִירָא לְמִשְׁלַט בַּהּ וְתִקְטוֹל יָת אִתְּתָא וְיָת בְּעִירָא אִתְקְטָלָא יִתְקַטְלוּן קְטָלָא חַיָבִין:
@54 וּגְבַר דִי יִסַב יָת אֲחָתֵהּ בַּת אֲבוּהִי אוֹ בַת אִמֵהּ וְיֶחֱזֵי יָת עֶרְיְתַהּ וְהִיא תֶחֱזֵי יָת עֶרְיְתֵהּ קְלָנָא הוּא וְיִשְׁתֵּיצוּן לְעֵינֵי בְּנֵי עַמְהוֹן עֶרְיַת אֲחָתֵהּ גַלִי חוֹבֵהּ יְקַבֵּל:
@55 וּגְבַר דִי יִשְׁכּוּב יָת אִתְּתָא סוֹאֲבָתָא וִיגַלֵי יָת עֶרְיְתַהּ יָת קְלָנַהּ גַלִי וְהִיא תְגַלֵי יָת סוֹאֲבַת דְמָהָא וְיִשְׁתֵּיצוּן תַּרְוֵיהוֹן מִגוֹ עַמְהוֹן:
@56 וְעֶרְיַת אֲחַת אִמָךְ וַאֲחַת אָבוּךְ לָא תְגַלֵי אֲרֵי יָת קָרִיבֵהּ גַלִי חוֹבְהֶן יְקַבְּלוּן:
@57 וּגְבַר דִי יִשְׁכּוּב יָת אִתַּת אַח אֲבוּהִי עֶרְיַת אַח אֲבוּהִי גַלִי חוֹבְהֶן יְקַבְּלּוּן בְּלָּא וְלָד יְמוּתוּן:
@58 וּגְבַר דִי יִסַב יָת אִתַּת אֲחוּהִי מְרָחָקָא הִיא עֶרְיְתָא דַאֲחוּהִי גַלִי בְּלָא וְלָד יְהוֹן:
@59 וְתִטְרוּן יָת כָּל קְיָמַי וְיָת כָּל דִינַי וְתַעְבְּדוּן יָתְהוֹן וְלָא תְרוֹקֵן יָתְכוֹן אַרְעָא דִי אֲנָא מָעֵיל יָתְכוֹן תַּמָן לְמִתַּב בַּהּ:
@60 וְלָא תְהָכוּן בְּנִימוֹסֵי עַמְמַיָא דִי אֲנָא מַגְלֵי מִן קֳדָמֵיכוֹן אֲרֵי יָת כָּל אִלֵין עֲבָדוּ וְרָחִיק מֵימְרִי יָתְהוֹן:
@61 וַאֲמָרִית לְכוֹן אַתּוּן תִּירְתוּן יָת אַרְעֲהוֹן וַאֲנָא אֶתְּנִנַהּ לְכוֹן לְמֵירַת יָתַהּ אַרְעָא עַבְדָא חַלָב וּדְבָשׁ אֲנָא יְיָ אֱלָהָכוֹן דִי אַפְרֵשִׁית יָתְכוֹן מִן עַמְמַיָא:
@62 וְתַפְרְשׁוּן בֵּין בְּעִירָא דַכְיָא לִמְסָאָבָא וּבֵין עוֹפָא מְסָאָבָא לִדְכֵי וְלָא תְשַׁקְצוּן יָת נַפְשָׁתֵיכוֹן בִּבְעִירָא וּבְעוֹפָא וּבְכֹל דִי תַרְחֵשׁ אַרְעָא דִי אַפְרֵשִׁית לְכוֹן לְסָאָבָא:
@63 וּתְהוֹן קֳדָמַי קַדִישִׁין אֲרֵי קַדִישׁ אֲנָא יְיָ וְאַפְרֵשִׁית יָתְכוֹן מִן עַמְמַיָא לְמֶהֱוֵי פָלְחִין קֳדָמַי:
@64 וּגְבַר אוֹ אִתְּתָא אֲרֵי יְהֵי בְהוֹן בִּדִין אוֹ דְכוּרוּ אִתְקְטָלָא יִתְקַטְלוּן בְּאַבְנָא יִרְגְמוּן יָתְהוֹן קְטָלָא חַיָבִין: פפפ:

@2 **דבר אל כל עדת בני ישראל.** מלמד שנאמרה פרשה זו בהקהל, מפני שרוב גופי תורה תלויין בה: **קדשים תהיו.** הוו פרושים מן העריות ומן העברה, שכל מקום שאתה מוצא גדר ערוה אתה מוצא קדשה, אשה זונה וחללה וגו' אני ה' מקדשכם, (ויקרא כא ז. ח) ולא יחלל זרעו אני ה' מקדשו (ויקרא כא טו) קדשים יהיו אשה זונה וחללה וגו' (ויקרא כא ו. ז) :
@3 **איש אמו ואביו תיראו.** כל אחד מכם תיראו אביו ואמו, זהו פשוטו. ומדרשו אין לי אלא איש, אשה מנין, כשהוא אומר תיראו, הרי כאן שנים אם כן למה נאמר איש, שהאיש ספק בידו לעשות, אבל אשה רשות אחרים עליה: **אמו ואביו תיראו.** כאן הקדים אם לאב, לפי שגלוי לפניו שהבן ירא את אביו יותר מאמו, ובכבוד הקדים אב לאם, לפי שגלוי לפניו שהבן מכבד את אמו יותר מאביו, מפני שמשדלתו בדברים: **ואת שבתתי תשמרו.** סמך שמירת שבת למורא אב, לומר אף על פי שהזהרתיך על מורא אב, אם יאמר לך חלל את השבת אל תשמע לו, וכן בשאר כל המצות: **אני ה' אלהיכם.** אתה ואביך חיבים בכבודי, לפיכך לא תשמע לו לבטל את דברי. איזהו מורא, לא ישב במקומו ולא ידבר במקומו ולא יסתור את דבריו. ואיזהו כבוד, מאכיל ומשקה, מלביש ומנעיל, מכניס ומוציא:
@4 **אל תפנו אל האלילם.** לעבדם. אלילים לשון אל, כלא הוא חשוב: **ואלהי מסכה.** תחלתן אלילים הם, ואם אתה פונה אחריהם, סופך לעשותן אלהות: **לא תעשו לכם.** לא תעשו לאחרים ולא אחרים לכם. ואם תאמר לא תעשו לעצמכם אבל אחרים עושין לכם, הרי כבר נאמר (שמות כ ג) לא יהיה לך, לא שלך ולא של אחרים:
@5 **וכי תזבחו** וגו' **.** לא נאמרה פרשה זו אלא ללמד שלא תהא זביחתן אלא על מנת להאכל בתוך הזמן הזה, שאם לקבוע להם זמן אכילה, הרי כבר נאמר (ויקרא ז טז) ואם נדר או נדבה זבח קרבנו וגו' : **לרצנכם תזבחהו.** תחלת זביחתו תהא על מנת נחת רוח שיהא לכם לרצון, שאם תחשבו עליו מחשבת פסול לא ירצה עליכם לפני: **לרצנכם.** אפיימנ''ט [פיוס] . זהו לפי פשוטו. ורבותינו למדו (חולין יג א) , מכאן למתעסק בקדשים שפסול, שצריך שיתכון לשחוט:
@6 **ביום זבחכם יאכל.** כשתזבחוהו, תשחטוהו על מנת לאכלו בזמן שקבעתי לכם כבר:
@7 **ואם האכל יאכל** וגו' **.** אם אינו ענין לחוץ לזמנו, שהרי כבר נאמר (ויקרא ז יח) ואם האכל יאכל מבשר זבח שלמיו וגו' , תנהו ענין לחוץ למקומו. יכול יהיו חייבין כרת על אכילתו, תלמוד לומר (שם) והנפש האכלת ממנו עונה תשא, ממנו ולא מחברו, יצא הנשחט במחשבת חוץ למקומו: **פגול.** מתועב, כמו (ישעיה סה ד) ומרק פגולים כליהם:
@8 **ואכליו עונו ישא.** בנותר גמור הכתוב מדבר ואינו ענוש כרת על הנשחט חוץ למקומו שכבר מיעטו הכתוב. וזהו בנותר גמור מדבר. ובמסכת כריתות (ה א) למדוהו מגזרה שוה:
@9 **לא תכלה פאת שדך.** שיניח פאה בסוף שדהו: **ולקט קצירך.** שבלים הנושרים בשעת קצירה אחת או שתים, אבל שלש אינן לקט:
@10 **לא תעולל.** לא תטל עוללות שבה והן נכרות. איזהו עוללות כל שאין לה לא כתף ולא נטף: **ופרט כרמך.** גרגרי ענבים הנושרים בשעת בצירה: **אני ה' אלהיכם.** דין להפרע ואיני גובה מכם אלא נפשות, שנאמר (משלי כב. כג) אל תגזל דל וגו' כי ה' יריב ריבם וגו' :
@11 **לא תגנבו.** אזהרה לגונב ממון, אבל לא תגנוב (שמות כ יג) שבעשרת הדברות, אזהרה לגונב נפשות, דבר הלמד מענינו, דבר שחיבין עליו מיתת בית דין: **ולא תכחשו.** לפי שנאמר (ויקרא ה כב) וכחש בה, משלם קרן וחומש. למדנו עונש, אזהרה מנין, תלמוד לומר ולא תכחשו: **ולא תשקרו.** לפי שנאמר (שם) ונשבע על שקר, ישלם קרן וחומש. למדנו עונש, אזהרה מנין, תלמוד לומר ולא תשקרו: **לא תגנבו ולא תכחשו ולא תשקרו ולא תשבעו.** אם גנבת, סופך לכחש, סופך לשקר, סופך להשבע לשקר:
@12 **ולא תשבעו בשמי.** למה נאמר, לפי שנאמר (שמות כ ז) לא תשא את שם ה' אלהיך לשוא, יכול לא יהא חיב אלא על שם המיוחד, מנין לרבות כל הכנויין, תלמוד לומר ולא תשבעו בשמי לשקר, כל שם שיש לי:
@13 **לא תעשק.** זה הכובש שכר שכיר: **לא תלין.** לשון נקבה מוסב על הפעלה: **עד בקר.** בשכיר יום הכתוב מדבר, שיציאתו מששקעה החמה, לפיכך זמן גבוי שכרו כל הלילה. ובמקום אחר הוא אומר (דברים כד טו) ולא תבוא עליו השמש, מדבר בשכיר לילה, שהשלמת פעלתו משיעלה עמוד השחר, לפיכך זמן גבוי שכרו כל היום, לפי שנתנה תורה זמן לבעל הבית עונה לבקש מעות:
@14 **לא תקלל חרש.** אין לי אלא חרש, מנין לרבות כל אדם, תלמוד לומר (שמות כב כז) בעמך לא תאר, אם כן למה נאמר חרש, מה חרש מיוחד שהוא בחיים אף כל שהוא בחיים, יצא המת שאינו בחיים: **ולפני עור לא תתן מכשל.** לפני הסומא בדבר לא תתן עצה שאינה הוגנת לו, אל תאמר מכור שדך וקח לך חמור, ואתה עוקף עליו ונוטלה המנו: **ויראת מאלהיך.** לפי שהדבר הזה אינו מסור לבריות לידע אם דעתו של זה לטובה או לרעה, ויכול להשמט ולומר לטובה נתכונתי, לפיכך נאמר בו ויראת מאלהיך המכיר מחשבותיך. וכן כל דבר המסור ללבו של אדם העושהו ואין שאר הבריות מכירות בו, נאמר בו ויראת מאלהיך:
@15 **לא תעשו עול במשפט.** מלמד שהדין המקלקל את הדין קרוי עול, שנאוי ומשקץ, חרם ותועבה. שהעול קרוי תועבה, שנאמר (דברים כה טז) כי תועבת ה' וגו' כל עשה עול, והתועבה קרויה שקץ וחרם, שנאמר (שם ז כו) ולא תביא תועבה אל ביתך והיית חרם כמוהו שקץ תשקצנו וגו' : **לא תשא פני דל.** שלא תאמר עני הוא זה והעשיר חיב לפרנסו, אזכנו בדין, ונמצא מתפרנס בנקיות: **ולא תהדר פני גדול.** שלא תאמר עשיר הוא זה בן גדולים הוא זה, היאך אבישנו ואראה בבשתו, עונש יש בדבר, לכך נאמר ולא תהדר פני גדול: **בצדק תשפט עמיתך.** כמשמעו. דבר אחר הוי דן את חברך לכף זכות:
@16 **לא תלך רכיל.** אני אומר על שם שכל משלחי מדנים ומספרי לשון הרע הולכים בבתי רעיהם לרגל מה יראו רע או מה ישמעו רע לספר בשוק, נקראים הולכי רכיל, הולכי רגילה אשפיימנ''ט בלע''ז [רגול] . וראיה לדברי, שלא מצינו רכילות שאין כתוב בלשון הליכה לא תלך רכיל, הולכי רכיל נחשת וברזל (ירמיה ו כח) , ושאר לשון הרע אין כתוב בו הליכה מלשני בסתר רעהו (תהלים קא ה) , לשון רמיה (שם קכ ב) , לשון מדברת גדולות (שם יב ד) , לכך אני אומר שלשון רכיל לשון הולך ומרגל, שהכ''ף נחלפת בגימ''ל, שכל האותיות שמוצאיהם ממקום אחד מתחלפות זו בזו, בי''ת בפ''א ובוי''ו, גימ''ל בכ''ף וקו''ף, נו''ן בלמ''ד, ורי''ש וז''ן בצד''י וכן (ש''ב יט כח) וירגל בעבדך, רגל במרמה לומר עלי רעה, וכן (תהלים טו ג) לא רגל על לשונו, וכן רוכל הסוחר ומרגל אחר כל סחורה, וכל המוכר בשמים להתקשט בהם הנשים, על שם שמחזר תמיד בעירות נקרא רוכל, לשון רוגל. ותרגומו לא תיכול קרצין, כמו (דניאל ג ח) ואכלו קרציהון די יהודיא, אכל ביה קרצא בי מלכא (ברכות נח א) . נראה בעיני שהיה משפטם לאכול בבית המקבל דבריהם שום הלעטה, והוא גמר חזוק, שדבריו מקימים ויעמידם על האמת, ואותה הלעטה נקראת אכילת קרצין, לשון קורץ בעיניו (משלי ו יג) , שכן דרך כל הולכי רכיל לקרוץ בעיניהם ולרמוז דברי רכילותן, שלא יבינו שאר השומעים: **לא תעמד על דם רעך.** לראות במיתתו ואתה יכול להצילו, כגון טובע בנהר, וחיה או לסטים באים עליו: **אני ה'.** נאמן לשלם שכר, ונאמן להפרע:
@17 **ולא תשא עליו חטא.** לא תלבין את פניו ברבים:
@18 **לא תקם.** אמר לו השאילני מגלך. אמר לו לאו. למחר אמר לו השאילני קרדמך. אמר לו איני משאילך כדרך שלא השאלתני, זו היא נקימה. ואיזו היא נטירה, אמר לו השאילני קרדמך. אמר לו לאו. למחר אמר לו השאילני מגלך. אמר לו הא לך ואיני כמותך, שלא השאלתני. זו היא נטירה, שנוטר האיבה בלבו אף על פי שאינו נוקם: **ואהבת לרעך כמוך.** אמר רבי עקיבא זה כלל גדול בתורה:
@19 **את חקתי תשמרו.** ואלו הן בהמתך לא תרביע כלאים וגו' , חקים אלו גזרות מלך שאין טעם לדבר: ובגד כלאים. למה נאמר, לפי שנאמר לא תלבש שעטנז צמר ופשתים יחדו (דבר' כב יא) , יכול לא ילבש גיזי צמר ואניצי פשתן, תלמוד לומר בגד. מנין לרבות הלבדים, תלמוד לומר שעטנז, דבר שהוא שוע טווי ונוז. ואומר אני נוז לשון דבר הנמלל ושזור זה עם זה לחברו, מישטי''ר בלע''ז [לערבב] , כמו (מועד קטן יב ב) חזיין לנאזי דאית בהון, שאנו מפרשין לשון כמוש פלישטר''א . ולשון שעטנז פרש מנחם, מחברת צמר ופשתים:
@20 **נחרפת לאיש.** מיועדת ומיוחדת לאיש, ואיני ידע לו דמיון במקרא. ובשפחה כנענית שחציה שפחה וחציה בת חורין המאורסת לעבד עברי שמתר בשפחה, הכתוב מדבר: **והפדה לא נפדתה.** פדויה ואינה פדויה וסתם פדיון בכסף: **או חפשה.** בשטר: **בקרת תהיה.** היא לוקה ולא הוא, יש על בית דין לבקר את הדבר שלא לחיבה (י''ג: לחיבו) מיתה: **כי לא חפשה.** ואין קדושיה קדושין גמורין. ורבותינו למדו מכאן שמי שהוא במלקות יהא בקריאה, שהדינים המלקין קורין על הלוקה (דברים כח נח, נט) אם לא תשמר לעשות וגו' והפלא ה' את מכותך וגו' : **כי לא חפשה.** לפיכך אין חיב עליה מיתה, שאין קדושיה קדושין, הא אם חפשה, קדושיה קדושין וחיב מיתה:
@22 **ונסלח לו מחטאתו אשר חטא.** לרבות את המזיד כשוגג:
@23 **וערלתם ערלתו.** ואטמתם אטימתו, יהא אטום ונסתם מליהנות ממנו: **שלש שנים יהיה לכם ערלים.** מאימתי מונה לו, משעת נטיעתו. יכול אם הצניעו, לאחר שלש שנים יהא מתר, תלמוד לומר יהיה, בהויתו יהא:
@24 **יהיה כל פריו קדש.** כמעשר שני שכתוב בו (ויקרא כז ל) וכל מעשר הארץ וגו' קדש לה'. מה מעשר שני אינו נאכל חוץ לחומת ירושלים אלא בפדיון, אף זה כן. ודבר זה הלולים לה' הוא, שנושאו שם לשבח ולהלל לשמים:
@25 **להוסיף לכם תבואתו.** המצוה הזאת שתשמרו תהיה להוסיף לכם תבואתו, שבשכרה אני מברך לכם פרות הנטיעות. היה רבי עקיבא אומר דברה תורה כנגד יצר הרע, שלא יאמר אדם הרי ארבע שנים אני מצטער בו חנם, לפיכך נאמר להוסיף לכם תבואתו: **אני ה'.** אני ה' המבטיח על כך ונאמן לשמור הבטחתי:
@26 **לא תאכלו על הדם.** להרבה פנים נדרש בסנהדרין (סג א) אזהרה שלא יאכל מבשר קדשים לפני זריקת דמים, ואזהרה לאוכל מבהמת חלין טרם שתצא נפשה, ועוד הרבה: **לא תנחשו.** כגון אלו המנחשין בחלדה ובעופות, פתו נפלה מפיו, צבי הפסיקו בדרך: **ולא תעוננו.** לשון עונות ושעות, שאומר יום פלוני יפה להתחיל מלאכה, שעה פלונית קשה לצאת:
@27 **לא תקפו פאת ראשכם.** זה המשוה צדעיו לאחורי אזנו ולפדחתו, ונמצא הקף ראשו עגל סביב, שעל אחורי אזניו עקרי שערו למעלה מצדעיו הרבה: **פאת זקנך.** סוף הזקן וגבוליו. והן חמש שתים בכל לחי ולחי למעלה אצל הראש שהוא רחב ויש בו שתי פאות, ואחת למטה בסנטרו מקום חבור שני הלחיים יחד:
@28 **ושרט לנפש.** כן דרכן של אמוריים להיות משרטין בשרם כשמת להם מת: **וכתבת קעקע.** כתב המחקה ושקוע שאינו נמחק לעולם שמקעקעו במחט והוא משחיר לעולם: **קעקע.** לשון (במד' כה ד) והוקע אותם, (שמואל ב כא ו) והוקענום. תוחבין עץ בארץ ותולין אותם עליהם ונמצאו מחקין ותחובין בקרקע, פורפויינ''ט בלע''ז [נעוץ] :
@29 **אל תחלל את בתך להזנותה.** במוסר בתו פנויה לביאה שלא לשם קדושין: **ולא תזנה הארץ.** אם אתה עושה כן הארץ מזנה את פירותיה לעשותן במקום אחר ולא בארצכם. וכן הוא אומר (ירמיה ג ג) וימנעו רבבים וגו' :
@30 **ומקדשי תיראו.** לא יכנס בהר הבית לא במקלו ולא במנעלו ובאפונדתו ובאבק שעל רגליו. ואף על פי שאני מזהירכם על המקדש, את שבתותי תשמרו אין בנין בית המקדש דוחה שבת:
@31 **אל תפנו אל האבת.** אזהרה לבעל אוב וידעוני. בעל אוב זה פיתום המדבר משחיו. וידעוני מכניס עצם חיה ששמה ידוע לתוך פיו והעצם מדבר: **אל תבקשו.** להיות עסוקים בם, שאם תעסקו בם אתם מטמאין לפני ואני מתעב אתכם: **אני ה' אלהיכם.** דעו את מי אתם מחליפין במי:
@32 **מפני שיבה תקום.** יכול זקן אשמאי, תלמוד לומר זקן, אין זקן אלא שקנה חכמה: **והדרת פני זקן.** איזהו הדור, לא ישב במקומו ולא ידבר במקומו ולא יסתור את דבריו. יכול יעצים עיניו כמי שלא ראהו, לכך נאמר ויראת מאלהיך, שהרי דבר זה מסור ללבו של עושהו, שאין מכיר בו אלא הוא, וכל דבר המסור ללב נאמר בו ויראת מאלהיך:
@33 **לא תונו.** אונאת דברים. לא תאמר לו אמש היית עובד עבודה זרה ועכשיו אתה בא ללמוד תורה שנתנה מפי הגבורה:
@34 **כי גרים הייתם.** מום שבך אל תאמר לחברך: **אני ה' אלהיכם.** אלהיך ואלהיו אני:
@35 **לא תעשו עול במשפט.** אם לדין, הרי כבר נאמר לא תעשו עול במשפט (פסוק טו) , ומהו משפט השנוי כאן, הוא המדה והמשקל והמשורה. מלמד שהמודד נקרא דין, שאם שקר במדה הרי הוא כמקלקל את הדין וקרוי עול, שנאוי, ומשקץ, חרם ותועבה. וגורם לחמשה דברים האמורים בדין מטמא את הארץ, ומחלל את השם, ומסלק את השכינה, ומפיל את ישראל בחרב, ומגלה אותם מארצם: **במדה.** זו מדת הארץ: **במשקל.** כמשמעו: **ובמשורה.** היא מדת הלח והיבש:
@36 **אבני צדק.** הם המשקולות ששוקלין כנגדן: **איפת.** היא מדת היבש: **הין.** זו היא מדת הלח: **אשר הוצאתי אתכם.** על מנת כן. דבר אחר אני הבחנתי במצרים בין טפה של בכור לטפה שאינה של בכור, ואני הנאמן להפרע ממי שטומן משקלותיו במלח להונות את הבריות שאין מכירים בהם:
@39 **ואל בני ישראל תאמר.** ענשין על האזהרות: **מות יומת.** בבית דין, ואם אין כח לבית דין עם הארץ מסיעין אותן: **עם הארץ.** עם שבגינו נבראת הארץ. דבר אחר עם שעתידין לירש את הארץ על ידי מצות הללו:
@40 **אתן את פני.** פנאי שלי, פונה אני מכל עסקי ועוסק בו: **באיש.** ולא בצבור, שאין כל הצבור נכרתין: **כי מזרעו נתן למלך.** לפי שנאמר מעביר בנו ובתו באש (דברים יח י) , בן בנו ובן בתו מנין, תלמוד לומר כי מזרעו נתן למלך. זרע פסול מנין, תלמוד לומר בתתו מזרעו למלך: **למען טמא את מקדשי.** את כנסת ישראל, שהיא מקדשת לי, כלשון (ויקרא כא כג) ולא יחלל את מקדשי:
@41 **ואם העלם יעלימו.** אם העלימו בדבר אחד, סוף שיעלימו בדברים הרבה. אם העלימו סנהדרי קטנה, סוף שיעלימו סנהדרי גדולה:
@42 **ובמשפחתו.** אמר ר' שמעון וכי משפחה מה חטאה, אלא ללמדך שאין לך משפחה שיש בה מוכס שאין כלם מוכסין, שכלם מחפין עליו: **והכרתי אתו.** למה נאמר, לפי שנאמר ובמשפחתו, יכול יהיו כל המשפחה בהכרת, תלמוד לומר אותו. אותו בהכרת ולא כל המשפחה בהכרת, אלא ביסורין: **לזנות אחרי המלך.** לרבות שאר עבודה זרה שעבדה בכך, ואפלו אין זו עבודתה:
@44 **והתקדשתם.** זו פרישות עבודה זרה:
@46 **אביו ואמו קלל.** לרבות לאחר מיתה: **דמיו בו.** זו סקילה, וכן כל מקום שנאמר דמיהם בם. ולמדנו מאוב וידעוני שנאמר בהם באבן ירגמו אותם דמיהם בם (פסוק כז) . ופשוטו של מקרא, כמו דמו בראשו (יהושע ב יט) , אין נענש על מיתתו אלא הוא, שהוא גרם לעצמו שיהרג:
@47 **ואיש.** פרט לקטן: **אשר ינאף את אשת איש.** פרט לאשת קטן, למדנו שאין לקטן קדושין. ועל איזו אשת איש חיבתי לך: **אשר ינאף את אשת רעהו.** פרט לאשת גוי, למדנו שאין קדושין לגוי: **מות יומת הנאף והנאפת.** כל מיתה האמורה בתורה סתם אינה אלא חנק:
@49 **תבל עשו.** גנאי. לשון אחר מבלבלין זרע האב בזרע הבן:
@50 **משכבי אשה.** מכניס כמכחול בשפופרת:
@51 **ישרפו אתו ואתהן.** אי אתה יכול לומר אשתו הראשונה ישרפו, שהרי נשאה בהתר ולא נאסרה עליו, אלא אשה ואמה הכתובין כאן, שתיהן לאסור, שנשא את חמותו ואמה. ויש מרבותינו שאומרים, אין כאן אלא חמותו. ומהו אתהן, את אחת מהן, ולשון יוני הוא הן אחת:
@52 **ואת הבהמה תהרגו.** אם אדם חטא בהמה מה חטאה, אלא מפני שבאה לאדם תקלה על ידה, לפיכך אמר הכתוב תסקל. קל וחמר לאדם שיודע להבחין בין טוב לרע וגורם רעה לחברו לעבור עברה. כיוצא בדבר אתה אומר (דברים יב ב) אבד תאבדון את כל המקומות, הרי דברים קל וחמר, מה אילנות שאינן רואין ואינן שומעין על שבאת תקלה על ידם אמרה תורה השחת, שרוף וכלה, המטה את חברו מדרך חיים לדרכי מיתה על אחת כמה וכמה:
@54 **חסד הוא.** לשון ארמי חרפה (בראשית לד יד) חסודא. ומדרשו אם תאמר קין נשא אחותו, חסד עשה המקום לבנות עולמו ממנו, שנאמר (תהלים פט ג) עולם חסד יבנה:
@55 **הערה.** גלה. וכן כל לשון ערוה גלוי הוא, והוי''ו יורדת בתבה לשם דבר, כמו זעוה, מגזרת (אסתר ה ט) ולא קם ולא זע, וכן אחוה מגזרת אח. והעראה זו נחלקו בה רבותינו, יש אומרים זו נשיקת שמש, ויש אומרים זו הכנסת עטרה:
@56 **וערות אחות אמך** וגו' **.** שנה הכתוב באזהרתן, לומר שהזהר עליהן בין על אחות אביו ואמו מן האב בין על אחיותיהן מן האם, אבל ערות אשת אחי אביו לא הזהר אלא על אשת אחי אביו מן האב:
@57 **אשר ישכב את דדתו.** המקרא הזה בא ללמד על כרת האמור למעלה, שהוא בענש הליכת ערירי: **ערירים.** כתרגומו בלא ולד, ודומה לו (בראשית טו ב) ואנכי הולך ערירי. יש לו בנים קוברן, אין לו בנים מת בלא בנים, לכך שנה בשני מקראות אלו ערירים ימותו ערירים יהיו. ערירים ימותו, אם יהיו לו בשעת עברה, לא יהיו לו כשימות לפי שקוברן בחייו. ערירים יהיו, שאם אין לו בשעת עברה, יהיה כל ימיו כמו שהוא עכשו:
@58 **נדה הוא.** השכיבה הזאת מנדה היא ומאוסה. ורבותינו דרשו לאסור העראה בה כנדה, שהעראה מפורשת בה (פסוק יח) את מקורה הערה (לעיל יח) :
@60 **ואקץ.** לשון מיאוס, כמו (בראשית כז מו) קצתי בחיי, כאדם שהוא קץ במזונו:
@62 **והבדלתם בין הבהמה הטהרה לטמאה.** אין צריך לומר בין פרה לחמור, שהרי מבדלין ונכרין הם, אלא בין טהורה לך לטמאה לך, בין שנשחט רבו של סימן לנשחט חציו. וכמה בין רבו לחציו, מלא שערה: **אשר הבדלתי לכם לטמא.** לאסור:
@63 **ואבדל אתכם מן העמים להיות לי.** אם אתם מבדלים מהם הרי אתם שלי, ואם לאו הרי אתם של נבוכדנצר וחבריו. רבי אלעזר בן עזריה אומר מנין שלא יאמר אדם נפשי קצה בבשר חזיר, אי אפשי ללבוש כלאים, אבל יאמר אפשי, ומה אעשה ואבי שבשמים גזר עלי, תלמוד לומר ואבדיל אתכם מן העמים להיות לי, שתהא הבדלתכם מהם לשמי, פורש מן העברה ומקבל עליו עול מלכות שמים:
@64 **כי יהיה בהם אוב** וגו' **.** כאן נאמר בהם מיתה ולמעלה כרת. עדים והתראה בסקילה, מזיד בלא התראה בהכרת ושגגתם חטאת, וכן בכל חיבי מיתות שנאמר בהם כרת:
@65 **הלא כבני כושיים אתם לי.** למה אמנע מלהפרע מכם אחרי אשר אינכם שבים אלי הלא מן בני נח באתם כשאר עכו"ם ככושיים אשר נדמיתם להם כענין שנאמר ( ירמיה יג ) היהפוך כושי עורו כך אתם תוכלו להטיב: **הלא.** בטובתי תחילת בוחרי בכם היא הוצאה שהוצאתי אתכם מארץ מצרים ומה לי בכך אף פלשתים כך הוצאתי מכפתור כשבאו כפתורים על עוים כענין שנאמר ( דברים ב ) והעוים היושבים בחצרים עד עזה וגו' כבשו גם בני עזה ושאר סרני פלשתים תחתיהם והוצאתים מידם ואעפ"כ לא עשיתים לי לעם: **וארם מקיר.** וכן אני עתיד להעלות את ארם מקיר שיגלם שם סנחריב ולקץ הימים משתבטל מלכות אשור יצאו:
@66 **והשמדתי אותה.** הממלכה הם בית יהוא אבל בית יעקב לא אשמיד:
@67 **כי הנה אנכי מצוה.** להגלותם ולהניעם בכל הגוים הנעה רבה ויתירה כאשר ינוע מה שכוברין בכברה לאחר שנפלו ממנו סובין הדקין ונותרו הגסין שאין יכולין לצאת ואז המנענע מנענע בכל כחו: **ינוע.** על ידי אחר ולא יתכן לקרות ינוע שהוא דבר הנע מאליו:
@68 **לא תגיש ותקדים בעדינו הרעה.** בשביל עוונינו לא תמהר הרעה לגשת ולבא:
@69 **ביום ההוא.** אחרי בא עליהם כל אלה יבא יום ההוא המוכן לגאולה ובו אקים סוכת דוד הנופלת, י"ת מלכותא דבית דוד:
@70 **למען יירשו.** ישראל את שארית וגו' ואת כל העכו"ם כי נקרא שמי עליהם. אשר. כמו כי:
@71 **ונגש חורש בקוצר.** והשיג דיש את בציר ובציר ישיג את זרע ( ויקרא כו ) לא יספיקו לחרוש עד שיבא הקציר ולא יספיקו לבצור עד שיבא עת הזרע: **תתמוגגנה.** תרגם יונתן יתפלחן, קרקע עבודה מתמוגגת בבא גשמים: **עסיס.** יין טוב ומתוק:
@75 **אם אדרש לכם.** בבקשתכם ובסוף הספר הזה הוא אמר אדרש לבית ישראל זו אחת מן המקומות המלמדים אותנו שהקב"ה חוזר בו על הרעה ועל כיוצא בזה ההוא אמר ולא יעשה ( במדבר כג ) מדרש תנחומא:
@76 **התשפוט אותם.** לשון ויכוח:
@77 **ביום בחרי בישראל.** הרי שהיתה שנאה זו כבושה לפני המקום קרוב לתשע מאות שנה משהיו במצרי' עד יחזקאל והיתה אהבתו מחפ' עליהם ועל ידי שהיו עתה מרבים לפשוע נתעוררה ועל זה נאמר שנאה תעורר מדנים וגו' ( משלי י ):
@79 **ואומר אליהם.** אהרן ניבא להם נבואה זו קודם שנגלה הקב"ה על משה בסנה וזהו שנאמר ( שמואל א ב ) לעלי הנגלה נגלתי אל בית אביך בהיותם במצרים וגו':
@80 **וימרו בי.** הם הרשעים רובם של ישראל שמתו בשלשת ימי אפלה כמו שנאמר וחמושים עלו בני ישראל וגו' ( שמות יד ) אחד מחמשים ויש אומרים אחד מחמש מאות:
@81 **לבלתי החל.** שלא יתחלל שמי מאחר שנודעתי להם והבטחתים להוציאם והכירו מצרים שהם עמי אילו הייתי משחיתם היו אומרים אויביהם מבלתי יכולת בידו להוציאם:
@84 **להיות לאות.** אות גדול הוא להם שנתתי את יום מנוחתי להם למנוחה הרי היכר גדול שקדשתים לי:
@85 **בחוקותי לא הלכו.** נסו אותי בעגל וברפידים מלקבל את התורה והותירו מן המן: **ואת שבתותי חללו.** יצאו מן העם ללקוט מן:

@2 **קדושים תהיו כי קדוש אני יי' אלהכם.** רוצה לומר שתתקדשו מחסרונו' החומר ותפרדו מעניינו בתכלי' מה שאפשר לכם ובזה תדמו לו לפי מה שאפשר כי אני נבדל מחמר ונקי ממנו בכל האופנים:
@3 **איש אמו ואביו תיראו.** צוה במורא ההורים כי בזה תועלת נפלא לקבל האדם מוסרי התורה וזה כי ההורים יסרו זרעם ויקנו להם המוסר אשר ישמרו בו מהשחית עצמם וזולתם כי זאת התכונה היא להורים בטבע לאהבת זרעם ולזה ישמרו בכל האופנים שאפשר שלא יוזקו מצד רוע מנהגיהם בפעולותיהם ושלא יזיקו זולתם לשמרם שלא יזיקום ועם זה ג"כ ייסרום שלא יטו אל רוב המאכל והמשתה כדי שלא ישחיתו קנייניהם וזה כלו נמשך הוא לכוונת התורה אמר כי באשר ייסר איש את בנו יי' אלהיך מיסרך ולזה התחיל שלמה בספר משלי להזהיר על זה המוסר אמר שמע בני מוסר אביך ואל תטוש תורת אך ולהיות מוסר ההורים הישיר לקבול מוסר התורה הפליגה התורה בעונש הבן שלא יקבל מוסר ההורים כמו שיתבאר בדין סורר ומורה על שבזאת המצוה תועלת נפלא להישיר האדם ליראת השם יתע' וזה שאם צוונו לירא מההורים לפי שכבר היו כלי מה שתולדתינו כל שכן שיותר ראוי לאין שיעור לירא מהשם יתעלה שהוא סבה האמתית במציאותינו ובמציאות ההורים וזה שלא נוכל לייחס הויתנו עם מה שבה מיתרון החכמה אל זר האב והאם כי לא נמצא בהם אומנות בזה המעשה עד שיכונו לעשות האברים בזה האופן הנפלא שהם עליו. ולזה יחוייב שיהיה הפועל האמיתי באלו ההויות שכל משיג מה שיעשהו כמו שביארנו בספר מלחמות יי'. והתבאר עוד במה שאחר הטבע. והנה יראת ההורים הוא לעשות מה שיצוו לעשות ולהשמר ממה שיזהירו מעשותו וכן יהיה מיראתם שלא לחלוק על דבריהם וכן תהיה מיראתם לשום מעלה גדולה בנפש ולזה יחוייב שלא יקל לשבת במקומם או לעמוד במקומם והוא מבואר שלא יחוייב מפני יראת ההורים לעבור את דברי השם יתע' כשיצוו על זה וזה כי יראתנו אותם הוא מפני מצות השם יתע'. ולזה ראוי שנירא יותר מהשם יתע' והוא מבוא גם כן שהאשה אחר שתנשא לא תמשול על זאת המצוה כי היא מוכרחת לעבוד בעלה ולזה לא ימשול האב להפר נדריה בהיותה בית איש אבל ימשול עם זה אישה כי היא מוכרחת להמשך לרצונו כמו שיתבאר בפרשת ראשי המטות:
@3 **את שבתותי תשמורו.** העירנו בזה כי ביראת ההורים תועלת במדות ובדעות כמו העניין בשמירת שבתות השם יתעלה שיש בהם תועלת במדות ובדעות כמו שביארנו במצות שבת. ויתבאר עוד במה שיבא בשאר המועדות:
@4 **אל תפנו אל האלילים.** רוצה לומר שלא תפנו במחשבתיכם לענין האלילים שיהיה זה סבה שתזנו אחריהם והנה קרא הע"ז אליל להורות שאין בה ממש אבל הוא כמו הדבר שאין לו מציאות:
@4 **ואלהי מסכה לא תעשו לכם.** לפי שכבר אמר בפרשת יתרו לא תעשה לך פסל וכל תמונ אשר בשמים ממעל ואמר בזה המקום ואלהי מסכה לא תעשו לכם. הנה נלמד ביאור זה הענין מהעניינים הנמשכים לו וזה שבפרשת יתרו אמר תחלה לא יהיה לך אלהים אחרים ואח כך אמר לא תשתחוה להם וזה מורה ששם הורה על עשיית הפסל לא לעבדו. ובזה המקום לפי שסמכה אל העניין שהוא תוספת קדושה והוא אמרו אל תפנו אל האלילים הנה תהיה הכונה בזה שלא יעשה אלהי מסכה אפילו לזולתנו וזה כי גם הצורות שהם לנוי מנעה התורה שלא נעשם לנו כמו שהתבאר מאמרו ואלהי מסכה לא תעשו לכם ולזה הוא מבואר שנמנע ממנו מעשיית אלהי מסכה לנוי שאם היה לעבדו הנה הוא נכלל באמרו לא תעשה לך פסל ואם הוא לנוי נכלל באמרו ואלהי זהב לא תעשו לכם. ולזה תהיה הכונה בזה המקום שנזהר מעשיית אלהי מסכה גם לזולתינו והנה אמר לכם כי מדרך עושה מלאכה שינתן לו שכר עליה ולזה הוא עושה אותו בעבורו לא בעבור בעל המלאכה ורצתה התורה בזה אף על פי שלא נכוין בזה הפועל בעבור עבודה זרה אבל בעבורנו והוא לקחת שכר מזה המעשה הנה עם כל זה הוא אסור וזהו תוספת הקדושה אשר בזאת האזהרה וכי תזבחו זבח שלמים ליי'. אותם כבר נתבאר זה הדין מהשלמים בפרת צו ומשם יתבאר כי אמרו ואם האכול יאכל מבשר זבח השלמים ביום השלישי רוצה לומר אם יחשוב עליו שיאכל ביום השלישי על יד המקריב אותו באופן שביארנו שם:
@9 **ובקוצרכם את קציר ארצכם לא תכלה פאת שדך לקצור.** צותה התורה בזה לחונן הדלים ממה שהשפיע השם יתעלה לאדם מן הטובות והנה יקל לאדם להניח להם מעט מהקמה כי זה ממה שלא החזיק בו עדיין וכן הענין בשאר המתנות האלו שזכר בזה המקום ואולי אם ימתין עד בא קצירו ותבואתו לידו יקשה בידו לתת לו זה אבל על כל פנים אם לא הניח הפאה באופן שצותה התורה או הלקט או העוללות או הפרט כבר תחייב לתת לעניי ממה שבא בידו מזה שנאמר לעני ולגר תעזוב אותם הנה הוא מצוה לעזבם על כל פנים לעני ולגר והנה הפאה הוא לפי מה שיורה עליו הגדר בסוף השדה כי הוא מה שתכלה אליו הקציר והוא מבואר מצד עצם הענין שבאי זה מקום שתכלה הקציר' וכל להניח פאה אף על פי שהוא באמצע שדהו כי לא דקדקה התורה אלא שיניח קצת מהקמה לעניים ואין הבדל לעניים בין היותר באמצע השדה או בסוף השדה והנה הקצירה תאמר על מה שילקט כלו כאחד והוא אוכל ומכניסו לקיום וגדולו מן הארץ כמו תבואת השדה והוא מבואר עוד שהוא בלתי נוהג במה שאין לו בעלים כמו ההפקר שנאמר פאת שדך ומזה יתבאר שזה בלתי נוהג בשדה הקדש ובשדה הנכרי שאין אני קורא בהם שדך וראוי שיובן מזה שכן הדין במה שיתלש יחד כי התלישה בו דומה לקצירה בתבואת השדה ואמנם זכרה התורה התבואות הנקצרות כי זהו היותר נהוג. והנה נדר הקצירה היא לקיטת התבואות על ידו או על יד שלוחו לתכלית שיאסף זה אל ביתו אמנם מה שישחית הבעלי חיים או ילקטו אותו הלסטים לעצמם או שישחת באון אחר לא יקרא קצירה. וכן לא יקרא קצירה אם קצר זה קודם שתהיה התבואה ההיא ראויה לקצור באופן מהאופנים אבל יהיה השחתה לא קצירה והוא מבוא עוד שאין ראוי שיניח מן השדה על חברתה כי אין זה פאת השדה הנקצרת והוא מבואר שמאלו המתנות אין בהם דבר לכהנים וללויים אבל הם לעניים שנאמר לעני ולגר תעזוב אותם וראוי שתדע שכאשר יגיע העת שלא ילכו העניים עוד לבקש בשדות ובכרמים אלו המתנות יוכלו הבעלים ללקחם שאם יעזבו אותם שם לא יהיו לעני ולגר אבל לעורבים ולעטלפים וכיוצא בהם וזה הפך כוונת התורה:
@9 **ולקט קצירך לא תלקט.** הנה לקט הוא לפי הוראת הגדר מה שיפול מתך ידו בלקטו השבולים הנקצרות או הנופל מתוך המגל שהוא כלי ללקט כאלו תאמר שנשארה שם שבולת אחת או שתים שלא נקצרו ולא נשאר סביב דבר יקצרו עמו ואולם בזולת זה האופן לא יהיה לקט והנה הוא שבולת אחת או שתים יחד אבל אם היה יותר מזה הנה הוא קציר לא לקט הקציר והוא מבואר מצד הוראת הגדר:
@10 **וכרמך לא תעולל.** רוצה לומר שלא תקח העוללות והנה העוללות הם מגזרת עולל שהוא קטן והם לפי הוראת הגדר הענבים חסרי ההווייה שאין משדרתם מסתעפים אשכולות ואין גרגיריהם מתקבצים זה על זה כגון העניין בענבים השלמים אבל גרגיריהם מפוזרים והנה יתבאר מזה שאפי' היה הכרם כלו עוללו' הנה הוא לעניים:
@10 **ופרט כרמך לא תלקט.** פרט הם הגרגרים הנפרטים מהענבים בעת הבצירה וזה כנפרט ממנו מה שאין בעל הבית מקפיד לו לפי הנהוג כמו אם נפרט גרגיר אחד או שנים מאחד מהענבים לא יותר מזה ולזה ראוי שלא ישימו הבוצרים הסל תחת הענבים בעת הבצירה כדי שיפול שם הפרט והוא מבואר שזה הדין יהיה בלקיטתם הענבים בסל ואולם אם שמו הענבים בקרקע בעת הבצירה וחזרו ולקטום משם יהיה פרט אפילו אשכול כי ממנהגם שלא יקפידו האנשים בזה כשיהיה בזה האופן וזה מבואר מן החוש והיה זה כן כי יחסו קטן אל מה שלקטו משם ולזה יקלו האנשים בזה כשהיתה הלקיטה בזה האופן וכבר יתבאר שלמות אלו הדינין בפרשת כי תצא:
@10 **לעני ולגר תעזוב אותם.** ראוי שתדע שהקציר בא לפי הנהוג משנה לשנה ומי שאין לו מהענינים מה שאפשר שיסתפק בו שנה אחת הוא הנקרא עני לזה הענין וזה מבואר מאד כי מה יעשה זה שיש לו כדי פרנסת קצת השנה הימצאו לו אלו המתנות בעת שתחסר לו פרנסתו. והנר הוא גר צדק שקבל עליו לקיים כל התורה וזכרה אותו התורה לפי שיתכן יותר שיהיה עני כי אין לו חלק ונחלה בארץ לפי מה שיתבאר כי מה שיקנה מן הקרקעות ישוב לבעליו בעת היובל:
@11 **לא תגנבו.** היא האזהרה על גנבת ממון וזה יתבאר מהענינים הנלוים לו וכבר נתבאר העונש על גנבתו בפרשת ואלה המשפטים:
@11 **ולא תכחשו.** מפני שהזכירה התורה בפרשת ויקרא העונש על מי שכחש בעמיתו בפקדון או בתשומת יד או בגזל ונשבע על שקר כי האזהרה בזה המקום שלא לכחש ושלא לשקר רוצה לומר שאם כחש לא ישבע על זה לשקר וכבד נתבאר שם העונש:
@12 **ולא תשבעו בשמי לשקר.** הוא האזהרה מעבור על שבועת בטוי שנתבאר העונש בזה בפרשת ויקרא ונתבאר בזה המקום שכבר יעברו על השבועה אף על פי שאינה בשם המיוחד כיון שהיא בשם מהשמות שנקרא בהם השם יתעלה שנאמר ולא תשבעו בשמי לשקר בכל שם שהוא שמי:
@12 **וחללת את שם אלהיך.** הוא מבואר ששבועת שקר הוא חלול הש"י שאם היתה גדולה מעלתו אצל הנשבע כראוי היה נשמר תכלית השמירה שלא ישבע בשמו הנכבד לשקר:
@13 **לא תעשוק את רעך ולא תגזול.** הנה הגזלה הוא דבר הנגזל בעין מיד הבעלים בחזקה כמו שאמר ויגזול את החנית מיד המצרי והעושק הוא מה שיכבוש האדם מזולתו בחזקה ולא ירצה להשיבו לו כאלו תאמר שיכבוש שכר שכיר או הלואה או פקדון וכבר נתבאר בפרשת ויקרא שכבר יתחייב להשיב הגזלה או העושק עם שהוא מבואר בנפשו:
@13 **לא תלין פעולת שכיר אתך עד בקר.** הנה הלנת פעלת שכיר לא תהיה בשכיר לילה כי לא נתחייב לו השוכר שכירותו עד סוף הלילה ולזה תהיה זאת ההלנה בשכיר יום יום ונתנה התורה זמן לבעלים לפרוע השכיר עד סוף הלילה ומשם ואילך יתחייב בלא תעשה ומזה המקום יתבאר שכר שכיר לילה גובה כל היום עד הלילה ובבא הלילה יעבור עליו בלא תעשה כי היחס אחד ועליו אמרה תורה במה שיבא ביומו תתן שכרו:
@14 **לא תקלל חרש.** היא האזהרה שלא לקלל אחד מישראל והנה זכר החרש לפי שהוא בלתי שומע ובלתי מתפעל מזה ועם כל זה הזהיר על קללתו וכל שכן שראוי להזהר מלקלל מי שאינו חרש כי יקרו מזה קטטות והפסדים בקבוצים המדיניים ואולם המקלל את המת אינו חייב כי הוא בזה הדין למנה מהחרש וזה מבואר מהשרשים הכוללים. וראוי שתדע שלא יתחייב על הקללה אם לא יקלל בשם מהשמות המיוחדים לשם יתעלה כמו שביארנו בפרשת ואלה המשפטים:
@14 **ולפי עור לא תתן מכשול.** הרצון בזה שמי שהוא עור בדבר לא תתן מכשול לפניו להפילו כאלו תאמר אם שאל ממך מדבר מה אם הוא מותר או אסור ואמרת לו בדבר האסור שהא מותר או שאל ממך עצה ונתת לו עצה בלתי הוגנת להזיק לו באי זה אופן שיהיה או אם היה האיש ההוא בעל תכונות רעות והמצאת לו הדברים אשר בהם יעשה הרעות הנה בכל זה יעבור משום לפני עור לא תתן מכשול ומי ששם מכשול בדרך להפיל העובר שעובר שם עובר גם כן על זאת האזהרה ויתחייב עם זה בנזקיו לפי מה שנתבאר ממה שנזכר בפשרת ואלה המשפטים:
@15 **לא תעשו עול במשפט.** ראוי שתדע שעשיית העול במשפט יהיה משני צדדין אם שישפוט שלא כדין כשיזכה את החייב או כשיהיה ראוי לשפוט ולגמר הדין ולא יגמר הדין לחמוס על דין הזכאי ולהאריכו כי זהו גם כן עול בעניין המשפט ונכלל הנה כשלא יתנהג בענייני הדין כראוי להוציא המשפט לאור בעת הראוי לפי הדבר ההוא ויעשה זה בכונה לעשוק דין אחר מהבעלי דינין הנה הוא עובר על לאו זה ואמנם אם יעשה זה להוסיף חקירה באימות העניין אין זה עול אבל הוא יושר:
@15 **ולא תשא פני דל.** הנה הכונה בזה לפי הדברים הנלוים לו שלא תשא פני דל למשפט להטות המשפט מפני דלותו והנה הוצרכה התורה להזהיר בזה כי אולי יחשוב השופט כי מפני שהעשיר מחוייב לפרנס העי די מחסורו והיה האופן היותר שלם בזה שינתן זה לעני באופן שלא יבוש כמו שיתבאר בענין הצדקה הנה יהיה צדקה אם יזכה הדל ויתפרנס מהעשיר דרך כבוד לזה הוצרכה התורה להזהיר בזה בבאור כי על כל פנים ראוי שישפטו כדין:
@15 **ולא תהדר פני גדול.** רוצה לומר בבואו לדין ועניין ההידור שלא יכבדהו השופט בבואו לפניו לדין יותר מבעל דינו כטעם והדרת פני זקן והטעם בזה שאם יראה בעל דינו שהגדול מכובד בעיני השופט ירא שתהיה דעת השופט קרובה לו ויצטער מזה ויכאב לבו עד שלא יוכל לסדר טענותיו כראוי בפני השופט לו שבו שלא יועילו לו טענותיו:
@15 **בצדק תשפוט עמיתך.** לפי שלא צוה בזה אחר אמרו לא תעשו עול במשפט והמתין להזכיר זה אחר אלו הלאוין הוא מבואר שזו היא מצות עשה כנגד אלו הלאוין הקודמים ואמנם היותו כנגד לא תעשו עול במשפט. ולא תשא פני דל. הוא מבואר כי מי שיעשה עול במשפט או ישא פני דל במשפט איננו שופט בצדק וכן יתבאר כי מי שיהדר פני גדול איננו שופט צדק כי הוא ככה באופן מה אל שיתחדש עול במשפט כמו שקדם:
@16 **לא תלך רכיל בעמך.** ענין הרכילות הוא שיספר האדם דברים מאיש אחד לאיש אחר אף על פי שהם דברי אמת באופן שתוכל להתחדש בזה שנאה ותחרות ביניהם כי בזה מההפסד בקבוץ המדיני מה שלא יעלם והנה יתבאר מזה שהוא ראוי להזהר מלספר בגנות חברו וזה שאם הזהירה התורה מסיפור הדברים מלספר בגנות חברו וזה שאם הזהירה התורה מסיפור הדברים שיבאישו ריח האיש ההוא בעיני איש אחד או בעיני האנשים מיוחדים כל שכן שראוי שיזהר מסיפור הדברים שיבאישו ריח האיש ההוא בעיני האנשים כלם:
@16 **לא תעמוד על דם רעך.** זכרה התורה זאת האזהרה אחרי הלאו הקודם להורות שהרכילות מביאה להריגת נפשות והנה עניין זאת האזהרה שמי שיוכל למלט מהמות איש אחד אם בדבריו אם בהשתדלותו אם בפעולותיו הנה הוא עובר על זאת האזהרה:
@17 **לא תשנא את אחיך בלבבך.** רוצה לומר אף על פי שלא יזיק לו כלל כיון ששונא אותו בלבו עובר על זאת האזהרה והנה תועלת זאת האזהרה מבואר כי השנאה אפשר שתביאהו להמנע מהשתדלות בהצלתו ולזה סמך עניין זאת האזהרה לאזהרה הקודמת וכן אפשר שתביאהו השנאה להמנע מהוכיחו כשיעשה דברים בלי ראויים ולזה סמך לזה הצווי הנמשך לו הוכח תוכיח את עמיתך ולא תשא עליו חטא. רוצה לומר כשיעשה דבר כנגדך או כנגד השם יתעלה תוכיחנו כדי להשיבו אל הדרך הטובה והנה יש בתוכחתו אותו תועלת אם עשה דבר כנגדו כי אולי יתקן את אשר עותו או יראהו שלא עשה דבר כנגדו או אם עשה כנגד השם יתעלה יש בהוכחתו תועלת להשיבו מדרכו הרעה ולזה ראוי שתהיה הוכחתו אותו באופן שיתכן שיגיע מהתוכחה זה התכלית וזה יהיה כשיאמר לו בינו לבין עצמו דברים מושכים לבבו לעבודת השם יתע' ומרחיקים אותו מאלו הפעולות המגונות לא כשיאמר לו זה בקנטורא ושיספר בגנותו בפני בני אדם כי בזה התוכחת ישא עליו חטא המוכיח רוצה לור שכבר יהיה המוכיח חטא בזה בביישו אז בפני בני אדם ולזה הזהיר התורה שתהיה זאת התוכחת באופן שלא ישא עליו המוכיח חטא:
@18 **לא תקום ולא תטור את בני עמך.** באור אלו האזהרות למד מענינו שהוא במה שבין בני אדם מהעזר קצתם בקצת בדברים שדרך השכנים להעזר קצתם בקצת אשר יקשה בעיניהם כאשר לא יעזרו מהם בזה האופן וזה מבואר מן החוש בדברים המדיניים כי כבר יקשה לאדם בבקשו משכינו שישאלהו כלי מה מעט מהזמן ולא יתרצה להשאילו לו והוא מבואר כי מכמו אלו העניינים תתחדש בינם מריבה ואם יקח האיש נקמתו ממנו בכמו זה האופן תשאר השנאה ביניהם והמריבה ולזה הזהירה תורה לא יקום אבל אם יקרה שישאל ממנו כלי מה מי שמנע ממנו כליו ישאילהו לו כי בזה האופן תסור הקטטה מביניהם והזהירה עם זה שלא יטור בלבבו זה הענין כלל כדי שתסור הקטטה מביניהם ויהיו באהבה ולזה סמך לו הצווי הנמשך לזה. ואולם בנזקי הממון והחבלות לא הזהירה שלא יקום ולא יטור אבל התבאר במה שעבר שכבר יקח נקמתו ממנו על יד בית דין וכל שכן שלא הוזהר מהנטירה ולזה חוייב שתהיה הנקימה והנטירה בכמו אלו הדברים שאמרנו:
@18 **ואהבת לרעך כמוך.** רוצה לומר שיאהבהו כגופו ולזה יבחר לו כפי היכולת הטובות אפשריות לו וירחיק ממנו ההזיקי' כמו שיעשה זה לעצמו אלא שהמצוה בזה הוא באופן שלא יגיע בו נזק לאהוב מפני זאת האהבה ושלא יחוייב לאד' להניח מלאכתו מפני עשיית מלאכת חברו כי אהבתו עצמו קודמת לאהבתו זולתו וכן אם יקום עליו להרגו אינו מחוייב שיאהבהו ולא יזיק לו אבל יחוייב למלט את נפשו ואפילו בנפש הקם עליו וזה יתבאר באור שלם בפרשת נערה המאורשה:
@19 **אם חקתי תשמרו בהמתך לא תרביע כלאים.** הנה הרביעה רמז למשגל כמו שאמ' במה שקדם ואשה לא תעמוד לפני בהמה לרבעה. וענין זאת האזהרה הוא שלא ירביע דבר ממין אחד מהב"ח על נקבה ממין אחר ולפי שאינו מרביע אותם בהעלאותו אותתם זה על זה כי להם מעצמם התחלה בזה הפועל כשיאותו זה לזה למשגל או שלא יאותו הנה לא יעבור על זאת האזהרה אם העלם זה על זה אם לא הכניס בידו אבר הזכר באבר הנקבה והתועלת בזאת המצוה מבואר כי בזה מהפסד הסדר והיושר אשר בדברי' הטבעיים מה שלא יעלם עם שזה יהיה סבה להפסק התולדה מהנולד מכלאים כמו שהתבאר בספר ב"ח ולזה יפסד בזה האופן הרבה מהטוב שהשפיע השם יתע' באלו הנמצאות עם שזה יביא להאמין שאין בכאן צורה יתחלף בה דבר מדבר כמו שחשבו הרבה מהקודמים ובכלל הנה ההאמנה בשיש בכאן מינים מיוחדים יתחלפו קצתם מקצתם במהותם הוא מפני הצרה אשר בה ייוחד מין מין מהם ולזה צותה התורה בזה להחכימני כי זה ממה שיישירנו להשגתו יתעלה כמו שזכרנו פעמים רבות רוצה לומר ההאמנה במציאות הצורות:
@19 **שדך לא תזרע כלאים.** רוצה לומר שלא תזרע בו יחד שני מיני זרעים אלא אם היה הזרע האחד בשדה אחד והזרע השני בשדה אחר והתועלת בזאת האזהרה הוא התועלת אשר באזהרה הקודמת להישירנו שנאמין במציאות הצורות גם באלו הדברים היה אפשר שיחשב בהם שלא יתחלפו כי אם במקרי' כמו שחשבו קצת מהקודמים שיהיה התחלפות אלו הדברי' עם היותם מדברים אחדים בעצמם מצד התחלפות החלקים שמהם הרכבו במצב והסדר והתמונה וראוי שתדע כי זריעתו הזרעים כלאים הוא כשיהיה מהזרע האחד עם האחר שיעור מורגש ואולם אם היה באופן שיקרא כל הזרוע בשם הזרע אחד הנה הוא מבואר שאינו כלאים כי המדקדק לזרוע הזרע האחד לא יקפיד בזה השעור אם נתערב בו מזרע אחר והנה עמדו על זה השעור רבותינו ז"ל לפי מה שקבלו מפי משה רבינו ע"ה והוא אחד מכ"ד רצוני לומר שאם נתערב עם הזרע מזרעים אחרים אחד מכ"ד בתערובת ההוא הנה הם כלאים אבל בפחות מזה השעור אינם כלאים וזה אמנם יהיה כשנתערבו מיני תבואה או קטנית קצתה בקצת ואמנם אם נתערבו זרעוני גנה בתבואה או קטנית לא יהיה שיעורם אחד מכ"ד כי כבר יהיו פחות אחד מכ"ד כשנזרע ועם כל זה היה להם שיעור מורגש בנזרע והמשל כי זרע כרוב אם נתערב שיעור אחד ממנו בשלשים שיעורים מתבואה או קטנית הנה כמעט שיחזיק זרע הכרוב מהארץ הנזרעת שיעור שוה לשיעור שיחזיק בו זרע התבואה או הקטנית ולזה יהיה שיעורו אחד מעשרים וארבעה מהמקום שיזרע בו המעורב רוצה לומר שאם היה הזרע בהזרעו מחזיק שיעור אחד מהארץ כאלו תאמר אמה על אמה והתבואה שנתערב עמה מעשרים ושלש אמות מרובעות הנה הכל כלאים והנה מבואר שאין הסבה בהרחקת כלאי זרעים אלא מפני מראית העין לא מפני יניקתם מחלק אחד מהארץ שאם היה הדבר מפני היניקה לא היתה התורה אומרת שדך לא תזרע כלאים אבל תזהיר שלא תזרע הארץ כלאים ואמנם התורה לא הזהיר בזה והוא מבואר שאפשר לזרוע בשדה אחד חטים ובשדה אחר סמוך לו שעורים ומזה המקום יתבאר שאם היה המקום שזרע בו חיטים בלתי ראוי להקרא שדה אסור לו לזרוע סמוך לו שעורים וכן העניין בשאר זריע' והנה השעורי' יתחלפו לפי מנהג הדבר הנזרע והמשל כי זרעוני גנה יוזרע מהם יחד שיעור קטן כי המקום ההוא הוא שדה לפי הזרע ההוא ולזה אפשר לזרוע מהם במקום קטן מינים רבים והשעורים באלו הדברים עם שהם מקובלים מפי משה רבינו ע"ה הם עוד מבוארים מצד מנהג ההזרע באלו הזרעי' ולפי שהתורה לא חששה בכלאי זרעים אלא מפני מראית עין כמו שביארנו הנה כשיתערב בזרע הנזרע זרע שאין מה שיוציא ראוי לאכילה כי לא יתחייב עליו משום כלאים כי הרואה לא ישפוט שנזרע זה הזרע כלאים בכונה כי הוא בלתי ראוי לאכילה וראוי שתדע כי הזריעה תהיה אם כשיזרעו בידו אלו הזרעי' בשדה או כשיחפה אותם בעפר אם היו בארץ כי הוא ישים אותם זרעוני' בזה החפוי והוא מבואר שזאת האזהרה אינה נוהגת אלא בארץ ישראל כי היא תלויה בארץ וראוי שתדע מזאת האזהרה שאין בזרעי אילנות כלאים כי נזרעו יחד כי אין האילנות דומין לזרעי השדה שסמוכין זה לזה ולזה אם הקפידה התורה בזה בכמו אלו הזרעים אין ראוי שנלמד מהם זה הדין בזרעי האילנות כי הם בזה הדין למטה מזרעי השדה וזה כבר התבאר מהשרשים הכוללים ואולם יתבאר שהרכבת מין במין אילנות התורה אסרה וזה שאם הקפידה התורה בזרעים שלא יזרעו כלאים ואף על פי שכל אחד מהם גדל בפני עצמו כל שכן שתקפיד בהרכבת מין במין ולזה יתבאר שהמרכיב אילן באילן או ירק באילן לוקה:
@19 **ובגד כלאים שעטנז לא יעלה עליך.** כבר יתבאר במה שיבא שזה הכלאים הוא צמר ופשתים לבד שנאמר לא תלבש שעטנז צמר ופשתים יחדיו וידמה שלפי הוראת הגדר אמרו שעטנז על הבגד ששתיו פשתים וערב בו צמר או הפך זה ולזה אמר אחר כך שם צמר ושפתים יחדיו להורות שאיך שיהיה צמר ופשתים יחדיו הוא אסור ללבשו אף על פי שלא היה ארוג הצמר עם הפשתים אלא שהוא שוע עמו כמו הלבדים אם היו מצמר ופשתים או אם היה מחובר עמו חיבור ישים הצמר עם הפשתים כלי אחד ואפשר שיהיה שעטנז שם נאמר בכללות על אלו המינים שזכרנו מהחבור לצמר עם הפשתים ואיך שהיה הנה כשיתחברו הצמר עם הפשתים באחד מהאופנים הנזכרי' יהיה הבגד ההוא אסור ללבשו משום כלאים והוא מבואר מן התורה שאין אסור כי אם ללבשו אבל מותר להציעו מצע תחתיו שנאמר לא תלבש שעטנז ואמר בזה המקו' לא יעלה עליך ראיה שכבר יתכן לשומו תחתיו וראוי שתדע שלא יקרא צמר רק צמר הצאן ויתבאר שחבורי חבורין יחביר לענין כלאים והמשל שאם היה בכאן רצועה של עור והיה בצד אחר ממנה חוט של צמר נקשר בה ומצד השני חוט של פשתן אסור לחגור אותה כי הוא צמר ופשתים יחדיו כמו שהתבאר בט' מכלאים וכן העוש בגד מצמר ארנבי' וארג בו חוט של צמר מצד זה וחוט של פשתן מצד זה הרי זה אסור משו' כלאים כמו שנתבאר בחמישי מתוספו' כלאים ומזה המקו' יתבאר שהבגד של צמר שתפרו בו עורות והיו העורו' תפורין בפשתן או היה בהם חוט של פשתן קשור באופן שיהיה חבור הנה הוא כלאי' כי חבורי חבורים הם יחדיו כמו שביארנו עם שהוא מבואר בנפשו וכבר הארכנו בזה לפי מה שראינו בזמנינו זה רבים בלתי נשמרי' מזה ואם טען אדם עלינו ויאמר שאין שם כלאי' מן התורה אלא כשהיה שוע טווי ונוז כמו שנפסקה ההלכה בזה במסכת נדה כמר זוטרא שאומר עד שיהיה שוע טווי ונוז אמרנו לו שאין פסק ההלכה היא שם מחכמי התלמוד אבל מהגאונים הראשונים ולזה לא תשגיח בפסק ההלכה היא כי שם בתלמוד הלכות רבות שהם מהגאונים הראשונים כמו שזכר הרש"י בפירושו למסכת חולין ולזה הדעת נטה הרב המורה והנה תמצא בד' ממנחות רבא חולק על מאמר מר זוטרא בזה והתבאר בעירובין כי מר זוטרא היה תלמיד לרבא ומשרשינו בתלמוד שאין הלכה כתלמיד במקום הרב ועוד שזה המאמר הוא בנדה אגב גררא ולזה לא יתן רושם גדול בהאמתת זה הפסק ועוד שכל המשניות שהם בט' מכלאים מלאות מסתירת דעת מר זוטרא במסכת נדה ועוד שכבר יתכן שיפורש מאמר מר זוטרא במסכת נדה באופן בלתי סותר זה הדעת וזה שהוא יאמר כי מלשון שעטנז לא יתבאר שיהיה שוע או טווי או נוז אבל אם היתה הוראתו זאת ההוראה רוצה לומר שוע טווי ונוז היה ראוי יותר שיורה על מה שהוא שוע טווי ונוז יחד לא מה שהוא שוע או טווי או נוז ומזה הצד אמרו שם דהלכתא כמר זוטרא מראפקינהו רחמנא בחד לישנא והנה אף על פי שנודה שיהיה האמת מה שיאמ מר זוטרא כי לשון שעטנז יורה על מה שהוא שוע טווי ונוז הנה מה שאמרה התורה אחריו צמר ופשתים יחדיו כלל כל האופנים שיהיה בהם הבגד צמר ופשתים יחדיו. וכבר יצאנו ממנהגנו בזה הביאור ואמנם הביאנו לזה מה שזכרנו במה שקדם והנה התועלת בזאת האזהרה עם שהוא לפי מה שיראה להרחיק מההליכה בחקות הגוים הנה הוא התועלת בעינו אשר בשאר האזהרות הקודמות בעניין הכלאים וזה שהצמר הוא בא מן החי בהכרח החומר כמו שהתבאר בספר ב"ח. והפשתים הם באים מן הצמח והוא מין מכוון בעצמו. והנה יגיע מזה תועלת כי הצמר והפשתים עם היותם מסכימים ברכות והספוגיות ושמהם יעשו בגדים לאדם הנה יש בהם הבדל עצמו מצד צורותיהם כי זה מהצמח וזה מהחי והפשתים הוא צמח יותר שלם מהצמר כמו שיתבאר מפועל הצמיחה בפשתי' ובצמר ועוד שהוא מין מהמיני' מכוון בעצמו והצמר אינו כי אם מהכרח החמר וכל זה להחכימנו בזה האופן להשיג מציאות הצורות והמדרגות הנמצאו' קצתם עם קצת כי מזה נעמוד על מציאות הש"י כמו שזכרנו פעמים רבות:
@20 **ואיש כי ישכב את אשה שכבת זרע.** התבאר במה שקדם שזאת השכיבה תהיה אפשרית בקטן בן ט' שנים ויום אחד והנה זאת השכיבה הוא שישכב עמה כדרכה ויגמור ביאתו כי כבר אמר הכתוב שכבת זרע:
@20 **והיא שפחה נחרפת לאיש.** ר"ל בעולת בעל ולפי שאין אישות לגוי כמו שהתבאר למדנו שזה האיש הוא ישראל ולא יהיה זה בזולת איסור אלא בעבד עברי שכבר התבאר בפרשת ואלה המשפטים שרבו מוסר לו שפחה כנענית ולפי שכבר התבאר שם שאין לו אישות בה ולזה תהיה האשה וילדיה לאדוניה בצאתו ולא תשאר נקשרת עמו כלל בקשר האישות הנה הוא מבואר שזאת השפחה היא בת חורין בצד ושפחה בצד וזה אמנם יהיה כשתהיה משני שותפין וכתב לה אחד מהם גט שיחרור או שנפדית ממנו ונשארה חציה שפחה וחציה בן חורין והנה יהיה הרצון בנחרפת בעולה מענין חרפה כי זה הענין הוא חרפה לנו רוצה לומר המשגל כי הוא לאדם מצד שהוא ב"ח לא מצד שהוא אדם או יהיה מענין כריעה ונפילה ובזה נקראת חורף התקופה שישפל בה השמש תכלית השפלות במקומות מהארץ אשר בהם היישוב וכן אמר לא יחרף לבבי מימי רוצה לומר לא יפול ולא יכנע להודות לדבריכם ומזה הענין נקראו חרפות הדברים אשר יאמרו כנגד איש או אשה להשפיל מדרגתם. ולזה יהיה אמרו נחרפת לאיש נכרעת ונופלת לבעל לשכב עמה והנה לא אמרה התורה בעולת בעל לפי החסרון שיש בזאת הבעילה לפי הנימוס התוריי:
@20 **והפדה לא נפדתה וגו'.** רוצה לומר שאמנם קרא אותה שפחה מפני שלא נפדתה בשלמות או בכסף או בשוה כסף או לא נתן לה שטר שחרור וזה ממה שיורה גם כן שאין הכתוב מדבר במי שהיא שפחה בשלמות שאם היה הענין כן יהיה אמרו והפדה לא נפדתה אם חפשה לא נתן לה מותר אין צורך לזה:
@20 **בקורת תהיה.** ר"ל שהיא לוקה על זאת הבעילה אם היה זה בעדים והתראה:
@20 **לא יומתו כי לא חופשה.** מגיד שאם היה נשלם שיחרורה היו בני מות וזה ממה שיורה גם כן שהיא נשואה לישראל:
@21 **והביא את אשמו ליי'.** לפי שהיה מדבר מתחלה באיש וזכר מתחלה עונש השפחה קודם זכרו עונש הבועל למדנו שלא יחוייב האיש להביא אשם אם לא תתחייב היא מלקות כאלו אמר שכאשר תלקה היא אוז יחוייב להביא את אשמו ובכלל זה הנה יתבאר עוד מהמקומות הכוללים ומזה יתבאר גם כן שהוא יתחייב להביא אשם אם היה בן תשע שנים ויום אחד כיון שהיא לוקה על ידו:
@21 **איל אשם.** רוצה לומר האיל אשר יביאו לאשם והוא הבא בכסף שקלים כמו שהתבאר בפרשת ויקרא:
@22 **על חטאתו אשר חטא.** למדנו שהוא מביא אשם אחד על בעילות הרבה וממה שקדם יתבאר שלא יתחייב אשם אם לא היתה היא גדלה ובעולה ושתהיה מזידה:
@23 **וכי תבאו אל הארץ ונטעתם כל עץ מאכל וערלתם ערלתו את פריו.** למדנו מזה שהנוטע אילן מאכל בארץ ישראל יאסר פריו שלש שנים מיום שנטעו והנה קראו ערלה להורו' שהוא מותר אין בו תועלת כמו הענין בערלת הבשר וטעם זה הוא כי בהתחלה לא יתכן לרוב האילנו' שיתנו פרים באופן שישלם החום היסודי בו כי לכח הזן בהם טרדה במה שיצטר' לו מן המזון לגדול גופם ולזה לא יתחזק על שיהיה שם מהמזון מותר מצומק ומבושל יעשה ממנו הפרי וכבר תראה זה בביאור ביין ענבי הגפן הילדה שהו' חלוש החום היסודי מאד ולפי שרצתה התורה שיהיה ראשית פריו קדש הלולים ליי'. להעי' כי הש"י הוא הפועל באמת בכל הפעולו' הטבעיו' ומאתו הכל חוייב שימתין זה עד השנה הרביעית שיהיה נבחר מה שיהיה ליי':
@23 **שלש שנים יהיה לכם ערלים לא יאכל.** ראוי שתדע שהאכילה היא אחת ממיני ההנאה ולזה נלמד ממנה שפרי זאת הנטיעה אסור בהנאה שלש שנים ולפי שאמר ונטעתם כל עץ מאכל למדנו שאם נטעו לא למאכל פטור מן הערלה והוא מבואר שנטיעת ייחור מן האילן או זריעת זרע האילן הוא אחד לזה הענין וזה מבואר מהמקומות הכוללים. והנה הפרי הוא הכולל הקליפין והגרעינין אשר הם עמו וזה מבואר מצד הוראת הגדר:
@24 **ובשנה הרביעית יהיה כל פריו קדש הלולים ליי'.** רוצה לומר שיהללו עליו ליי' על כל הטובה אשר השפיע להם וזה אמנם הוא להעיד שכל הטובות הם מאתו יתע' ולפי שהוא קדש למדנו שיחוייב לאכלו בירושלם לפני' מן החומה כמו הענין בשאר הקדשי' כמו שיתבאר ואמנם קדשי הקדשים היו נאכלים לפנים מן הקלעים כמו שהתבאר ויתבאר שנטע רבעי פירותיו לבעלים ממה שנאמר בפרשת נשא ואיש את קדשיו לו יהיו ומזה יתבאר גם כן שמעשר בהמה הוא לבעלים נאמר בו קדש ליי' ובכלל הנה אם היה זה הקדש לכהן לא שתקה התורה מזה. ולפי שלא זכרה התורה בזה דבר הנה והוא מבואר שאלו הפירות לבעליהן ולפי שאמר כל פריו למדנו שאין בהם לעניים דבר ולא לכהני' וללויים:
@25 **ובשנה החמישית תאכלו את פריו.** אמר התורה זו שלא יכבד עלינו מה שמנעה התורה פירות שלשה שני' גם פיות השנה הרביעית לא התירה לאכל אותם כי אם במקום אשר יבחר כמו שקדם כי זה יהיה סבה שתדבק השגחת יתע' בנו ויוסיף לנו מפני זה תבואות הצמחים עם מה שישפיע לנו משאר הטובות ומהטובות האנושיות כמו שבארנו בספר מלחמות השם ואפשר עם זה שיהיה זה לתועלת שזכר הרבה המורה להרחיק מעבודות עבודה זרה הקדומות שהיו עושים פעולות מגונות למהר נתינת האילן פריו להוסיף תבואתו והתורה הערימה לעמוד כנגד הדיעות הנפסדות ההם לפי מה שאפשר לנקותנו מטמאתם:
@26 **לא תאכלו על הדם.** הנה מפני שסמך אל זה אמרו לא תנחשו ולא תעוננו למדנו שהאכילה על הדם היתה לכונה שיודעו להם העתידו' וזה אמנם היה שהיו זובחי' הב"ח והיה דמו יורד תוך הפיר' אחת וסביבה היו אוכלין בשר הב"ח ההוא ויחשבו שיהיו אוכלים בזה האופן עם השרים על שלחן אחד ותתחזק האהבה והחברה ביניהם עד שיודיעום השדים העתידות כמו שזכר הרב המורה שראה בספרים ההם:
@26 **לא תנחשו.** הוא שישפטו בדבר טוב או רע מפני דבר אחד בלתי מעיד עליו כלל כמו שיאמר אומ' לא אעשה דבר פלוני שייעדתי לעשות שאם אעשנו לא אשיג בו רצוני והעד על זה שהרי נפלה פתי מפי:
@26 **ולא תעוננו.** ר"ל שלא תשימו העתים סבת הדברים כמו שיעשו הסכלים שיאמרו יום פלוני מחדש פלוני או משנת פלוני טוב ויום פלוני רע כי זה כשלא יאמר בו יותר מזה השיעור הוא מביא להאמין שלא תהיה בכאן סבה פועלת ויהיה הכל מתחדש מהקרי כמו שחשבו רבים מהקודמים ואולם אם חברו עם העת מה שיתכן שיהיה סבת לזה לא יהיה בזה חטא והמשל אם אמרו העת פלוני קשה להקזה לפי שהשמש הוא אז במקום שתחמם האויר חום נפלא וכן אם בחרו לזרוע בעת מהשנה הנאות לזרוע מצד טבע התקופה וטבע הזרע לא יהיה בזה אשם וכמו זה אם אמרו שאין טוב לזמור הכרם בתחלת החדש אם היתה הגפן ילדה או בסוף החדש אם היתה הגפן זקנה כי אלו הדברים כלם הם מבוארי הסבות לפי מה שנתן השם יתעלה מהכח בכוכבים להשגיח באלו הנמצאות השפלות. וראוי שתדע שכן ההיקש במה שיתחייב משאר הכוכבים כי התורה העירה שהם נבראו להשגחה באלו הענינים השפלי' כמו שביארנו בפרשת בראשית ואולם החטא הוא כשיחם זה הענין אל דעת מופשט מסיבות אחרות וזהו מה שאמר רבי עקיבה בביאור זה כגון אלו שהן למודות ערבי שביעיות להיות יפות ולזה יהיה חטא במי שמחשב על פי האצטגנינות מזה הצד אלא אם יחס הפועל לכוכבים עצמם בזולת התחלה קודמת להם כי זהו מכת עבודה זרה בלי ספק ואולם מי שייחס הפועל לשם יתע' באמצעות הכוכבים ממה שנתן להם מהכח בזה לא יחטא בזה האופן אלא שראוי שלא יעלם ממנו שזה המשפט לא יתן האמת עכ"פ אבל ימצא בו הכזב הרבה לקצורנו מהעמידה על מה שיצטרך לעמוד עליו בנסיון למי שירצה שישפוט בזה משפט צדק עם שהשם יתע' הוא השליט על זה הסדור לבלבל אותו על צד ההשגחה כמו שביארנו בספר מ"י. ולזה ימצא בזאת ההודעה מהכזב הרבה ובכלל האזהרה הזאת מי שידמה להודיע העניינים הנעלמים באחיזת עינים כמו שיעשו קצת האנשים שיעשו נר מדברים ידועים וידליקו אותו ויהיה שם קטן שלא ראה קרי ויחשבו שהקטן יראה שם אמתת זה הדבר אשר בקשו לדעת ענינו איך הוא ואולי יקרה לו שיראה שם קצת דמיונים באחיזת עינים ומזה הסוג מה שיעשו שינעצו סכין בלחם אחד ובבא שם האיש החשוד על הדבר ההוא ידומה להם שיתנועע הלחם וזה הסוד מאחיזת עינים יתחייבו עליו מלקות ואמנם האוחז את העינים שהוא פטור הוא כאשר היה בדברים שידומו מפעולות הכשוף מזולת שיהיה כן כמו שתראה שיעשו אנשי' אחיזת עינים שידמה לאנשי' שעומדי' שם שתרנגול קטן ישא קורה גדולה ומה שידמה לזה:
@27 **לא תקיפו פאת ראשכם.** ידוע שמנהג עבוד הזרה היה להקיף פאת ראשם רוצה לומר לגלח אותה בתער וכבר נשאר רושם זה המנהג עד היום. והתורה צותה אלינו שלא נלך בחקותיהם כדי שנתרחק מדעותיהם הנפסדות בתכלית מה שאפשר עם שבזה תועלת להחכימנו ולהעמידנו על סודות הבריאה האנושית וזה שכבר יתבאר שחלקי הראש הם בלתי מתדמה הטבע ומזה הצד הבדילה התורה בין הקרחת והגבחת והנה הקפת הראש יביא לחשוב שיהיה הכל מטבע אחד כי טבע העגול אחד ומתדמה ולזה מנעה התורה זה כדי להעמידנו על הבדל הדברים כי עמידתנו על הבדל הדברים ומה שייוחדה בו קצתם מקצת תביאנו לעמוד על מהות הדברים וטבעיהם ומי שלא יחקור בזה האופן אבל יחשוב כל הדברים כלם מתדמים תבצר ממנו כל החכמה ויהיה זה סבה אל שיאמין שאין בכאן כי אם הצורה החמרית כמו שחשבו הרבה מן הקודמים ולפי שטבע פאת הראש הימנית הוא מתחלף לפאת הראש השמאלית הנה יתחייב על שתי אלו הפאות שתי מלקיות וראוי שתדע שהמגלח פאת חבירו הוא שיתחייב מלקות אף על פי שאינו הוא המתגלה ואמנם המתגלח לא יתחייב מלקות כי לא עשה מעשה ויתחייב שזה הדין הוא באיש לבד לפי שסמך ולזה ולא תשחית את פאת זקנך והאשה אין לה זקן ולזה יתבאר שהאשה שגלחה פאת ראשה או פאת ראש האיש פטורה:
@27 **ולא תשחית את פאת זקנך.** זאת ההשחתה היא לפי הוראת גדר גלוח בתער. והנה המקומות שהם פאה בזקן לפי הוראת הגדר הם חמש פאות שתים מימין אחת בלחי העליון ואחת בלחי התחתון ושתים כנגדן בשמאל ואחת במקום חבור לחי התחתון הימיני לשמאלי:
@28 **ושרט לנפש לא תתנו בבשרכם.** אחשוב כי הקודמים להשכם כי אין יתרון לאדם אחר המות היו שורטים בשרם כמו אחד מקרוביהם שלהם והתורה הזהירה מעשו' כמו זה הפועל המגונה ויתבא' שהוא חייב על כל שריטה ושריטה שנאמר ושרט לנפש לא תתנו וכן אם שרט שריטה אחת על מתים רבים חייב על כל מת ומת שנאמר לנפש לחייב על כל נפש ונפש:
@28 **וכתובת קעקע.** הוא כתב עשוי בצבע מהצבעים בעור האדם אחר הקרע במקום שיעבור בו הצבע. וזה היה מנהג הגוים בזמנים הקודמים לרשום על עצמם רושם העבודה זרה להורות שהם עבדים לה והזהירה התורה מעשות זה אפילו לשם יתעלה שלא לילך בחוקותיהם עם שהתורה בכללה היא להטיב לנו לא להכאיב גופותינו כמו שהיו עושים הסכלים ההם ולזה אמר כי גם את בניהם ואת בנותיהם ישרפו באש לאלהיהם ואולם השם יתע' נהג בזאת התורה השלמה מנהג האב עם הבנים שנשתדל להטיב להם בכל עוז ולשמרם מהפגעים ולזה אמרה במשנה תורה בנים אתם ליי' אלהיכם לא תתגודדו:
@29 **אל תחלל את בתך להזנותה.** זאת היא מצו' לא תעשה לא מנאה הרב המורה ועיינה שלא ימסור אדם בתו לביאה שלא לשם אישות:
@29 **ולא תזנה הארץ ומלאה הארץ זמה.** רוצה לומר שמי שיחלל בתו להזנותה יהיה סבה שתזנה הארץ כי היא תפקיר עצמה לכל ולא תבוש אחרי ראותה שאביה רוצה בזה ויהיה זה סבה שתמלא הארץ זמה כי יקרה מזה שלא יודע ממי הרתה ויבוא הענין שישא האב בתו והאח אחותו:
@30 **את שבתותי תשמורו ומקדשי תיראו אני יי'.** זכר אלו המצות יחד לפי שהם מתדמות בכוונותיהם כמו שיתבאר מדברינו בהם והנח' מורא המקדש הוא שלא יכנס בו שלא לצורך וינהג בו בכבוד וביראה כי זה מה שיישירהו לעמוד על הכוונה אשר בעבורה היה באופן הנפלא הזה שצוה השם יתע':
@31 **אל תפנו אל האובות.** ידוע ממה ששאל שאול באוב לאשה בעת אוב כי האוב הוא פועל יביא לדמות שהעלו בו המת ויתפעל הדמיון באון שיתדמה לו שהוא שומע קול מהמת ההוא יודעי לו העתידות והתבאר שזה הקול המדומה הוא נמוך מאד אמר שפל מאוב קולך וידמה שמה שנתפרסם מההודעה המגעת בכמו זה האופן בלקיחת גלגולת המת הוא מזה הסוג:
@31 **ואל הידעונים אל תבקשו לטמאה בה.** הנה הידעוני היה שהיו לוקחים עצם מעוף ששמו ידוע והיו משימים אותו בפיהם ויעשו פעולות להתבודד דמיונם עד שיגיע מזה שידברו בפיהם דברים ויחשבו שידעו בזה האופן מה שעתיד להיות והנה הפליגה התורה בהרחקת זה לפי שהיותר חזקה שבראיות על שיש בכאן שכל פועל כל אלו הדברים אשר בכאן היא ההודעה שתגיע מזה בחלום או בקסם או בנבואה כמו שבארנו בשני ממ"י ולזה תמצא שאמר הנביא מי פעל ועשה קורא הדורות מראש רוצה לומ' שהודעתו הדברים העתידים טרם היותם הוא ראיה חזקה על היותו פועל אותם ומי שישים סבת הודעת המתי' או העצמות יבטל שיהיה בכאן סדור מסודר משכל אבל יהיה החומר הוא התחלה לכל הדברים וזה בתכלית הגנות וההפסד:
@32 **מפני שיבה תקום.** הוא מצות עשה לקום מפני כל איש שיבה כדי לכבדו לא מנאה הרב המורה ובזה תועלת כי מפני זה ישמעו צעירי הימים לדברי הישישים ויהיו דבריהם אצלם יקרים ולזה יתנהגו במוסריהם כי הישישים לרוב מה שראו מעניני קורות העולם יודיעו להם על צד הנסיון דברים רבים בפיל וספיא המדינית ולזה יקרה למי שישמע דבריהם להנצל מהרבה מהפגעי' אשר היו באים עליו לולא עצת הישישים עם שבזה יתיישב בנפש לתת כבוד נפלא לשם יתעלה שהוא קדמון לא סר מהיות ונמצא ולא יסור:
@32 **והדרת פני זקן.** היא מצות עשה והרצון בזקן לפי הוראת הגדר חכם כי החכם יקרא זקן אף על פי שהוא צעיר לימים אמר זקנים משער שבתו והדור הוא לעמוד מפניו כדי להדרו:
@32 **ויראת מאלהיך.** ירצה בזה שזה יביאך לירא מאלהיך יראה עצומה כי גבוהה חכמתו לאין קץ על חכמת הזקן שתחוייב בו לכבדו ונפלאה קדימת מציאותו לאין קץ מקדימת מציאו' האיש הישיש:
@33 **וכי יגור אתכם גר בארצכם.** זה גר צדק:
@33 **לא תונו אותו.** ידמה שיהיה הרצון בזה אונאת דברים כלאו תאמ' שיזכיר לו מעש' אבותיו לביישו ולפי שצותה התורה לתת כבוד לראוי לו מפני החכמה והישישות צותה שלא לבזות אלו האנשים שתלויה מאחריה' קופה של שרצים:
@34 **ואהבת לו כמוך.** היא מצות עשה והוסיפה התורה לצוות על אהבתו ואם הוא נכלל במה שאמר לרעך כמוך לפי שיאהבוהו מהבלתי קרובים עם שכבר יקל לאדם להתנגד לו כי אין עוזר ולזה צותה התורה שנאהבהו כנפשנו:
@35 **לא תעשו עול במשפט במדה במשקל ובמשורה.** הכונה במשפט בזה הפסוק המשפט שיהיה ע"פ המדה והמשקל והמשורה. והמשל שהמודד הבגד בקנה המדה או המודד בארץ הוא השופט על פי המדה ההיא כמה ראוי שינתן אל זה האיש מהבגד או מהארץ או משאר העניינים הדומים וכן השוקל במאזנים אי זה משקל שיהיה מאיזה דבר שיהיה שופט על פי המשקל ההוא כמה יותן לזה האיש מהענין ההוא וכן הענין במשורה והיא המדה המכילה שעור מה מהפרות או מהמשקין ולזה ראוי שלא יטח השופט המשפט בשום צד מהצדדים:
@36 **מאזני צדק אבני צדק.** צותה התורה שיהיו הכלים הם בעצם שבהם ישלם המשקל בתכלית מהיושר והצדק באופן שלא יהיה עול מצדם במשקל והנה העול יהיה במאזנים מפנים רבי' מהם שיהיה מרחק הכפות מהאמצע מרחק בלתי שוה ומהם שיהיו קשי הנפילה או קלי הנפילה מאד ומהם שיהיו חוטי הכפות בלתי שוים בארך וכן ההקש בשאר הדברים אשר להם רושם כשלא ימצא הצדק במאזנים:
@36 **איפת צדק והין צדק.** הנה האפה היא מדת הפרות היבשים וההין היא מדת חלה והנה העול ימצא באיפה וההין אם היו חסרות או יתרות וכבר ימצא העול באפה מפני היותר מחזקת כשימחוה מצד אחד יותר ממה שתחזיק כשימחוה מצד השני וכן ימצא העול בכלי אשר ימחקו בו אם אינו ישר או הוא יותר כבד מן הראוי או יותר קל מהראוי:
@39 **ואל בני ישראל תאמר איש איש וגו'.** אחר שהזהיר מלהעביר זרעו למולך זכר הענש והיא סקילה אמר עם הארץ ירגמוהו באבן והוא מבואר שהסקילה תהיה בשני פנים אם שישליכו האבן על החוטא אם שישליכו החוטא על האבן אמ' במעמד הר סיני כי סקול יסקל או ירה יירה ולפי שהתורה אמר ואהבת לרעך כמוך ראוי שנבחר הקלה שבב' אלו המיתות ובכלל הנה מפני שתשלם מצות התורה בזה בקלה שבאלו המיתות הנה אין ראוי שנעשה יותר מזה כי בכמו אלו העניינים ראוי שנקח המעט שאפשר שתשלם בו כונת התורה והוא מבואר שההשלכה על האבן היא היותר קלה ההמתה וימצא בה יותר מעט הצער כי כבר נרדם בשרו הרדמה מה בנפילה באופן שלא ירגיש הרגש חזק במכת האבן כמו שהיה מרגיש בזה אם השליכו האבן עליו ולפי שאמרה תורה במה שיבא מענין הסקילה יד העדים תהיה בו בראשונה להמיתו ויד כל העם באחרונה למדנו שהעדים מתחילים מזה הפעל באופן שיהיה כדי להמיתו ולזה היו דוחפין אותו ממקום גבוה שיש בנפילה ממנו כדי המית ואם לא מת בזה משליכין עליו אבן שיש בה כדי להמית:
@40 **ואני אתן את פני באיש ההוא והכרתי אותו מקרב מקרב עמו.** הנה כבר התבאר במה שקד' ענין הכרת:
@40 **למען טמא את מקדשי.** כבר זכרנו במה שקד' כי הקדש הוא מצד הצורה וכל מה שהיתה יותר נקייה מחמר תהיה בו הקדוש' יותר ולזאת הסבה היתה מה שיעיר על הצורות הנבדלות נקרא קדש הקדשים ואין ספק כי מי שעושה מהאש אלוה לא יאמי' שתהיה בכאן צורה אבל תהיינה הפעולות הנמצאות לדברים הטבעיים מצד מה שבהם מהאש והוא החום היסודי אשר בהם והנה יטמא מקדש להשם ית' בהשיבו כחות הצורות האנושיות כלם מיוחסים על החמר ויחלל שם קדשו יתע' ר"ל שישיבהו חול כי הוא לא יאמין שתהיה בכאן התחלה זולת החמר ואמרה התורה שאם יעלימו עם הארץ את עיניהם לבלתי המית זה החוטא שנתחייב מיתה בב"ד הנה ישים הש"י פניו באיש ההוא ובמשפחתו ר"ל בנמשכי' אחריו כי מן השקר שיענשו משפחתו על חטאו ולזה אמ' והכרתי אותו ואת כל הזוני' אחריו לזנות אחרי המולך מקרב עמם מגיד שהזונים הם הנענשין על זה לאלהבלתי זונין אחריו:
@46 **איש איש כי יקלל את אביו.** לפי שכבר זכר בפרשת ואלה המשפטים שהמקלל אביו ואמו הוא במיתה בא לזכור בזה הפסוק באי זו מיתה הוא נענש ואמר דמיו בו רוצה לומר שאין ראוי שיחיה עוד ויתהוה בו דם מן המזון שהוא נזון ממנו אבל כל דמיו הם בו שאין ראוי שיתחדש בו עוד דם וזאת היה חמרה שבעברות לה יהיה העובר בה בסקילה שהיא חמורה שבמיתות אמ' בסוף זאת הפרשה באב' ירגמו אותם דמיהם בם:
@47 **ואיש כי ינאף את אשת איש.** כבר התבאר כי הנאוף ישלם משיהיה הבועל בן תשע שנים ויום אחד ואמנם ראוי שתדע כי האישות לא ישלם למי שאינו בן י"ג שנה ויום אחד כי קודם זה אין זרעו ראוי להולדה ואף על פי שהוא ראוי לביאה מהיותו בן תשע שנים ויום אחד וכבר התבאר זה במקומות הכוללים ולזה לא יתחייב מיתה על אשת קטן:
@47 **אשר ינאף את אשת רעהו.** מגיד שלא יתחייב מיתה כי אם על אשת בן ברית כי לא ישלמו תנאי האישות בזולת בני ברית ולזה תצא בשפחה כנענית שיוצאה בלא גט אחר שהיתה מיוחדת לעבד עברי וכן תמצא ביפת תאר שהותרה לישראל הוא שיהיה לה בעל או שלא יהיה לה בעל:
@47 **מות יומת הנואף והנואפת.** ראוי שתדע שכל מקום שנאמר מות יומת רוצה לומ' על ידי בית דין וזה מבואר מצד עצם הלשון וכל מקום שנאמר ימות רוצה לומר בידי שמים אמר פן ימות גם הוא כאחיו ולפי שלא ביארה התורה באי זה מיתה יומתו הנה יחוייב שיומתו במיתה יותר קלה שאפשר לב"ד שימיתוהו בה והוא מבואר ממה שאמרנו בענין הסקילה ולפי שהקלה באלו המיתו' הוא חנק הנה יומו בחנק:
@48 **ואיש אשר ישכב את אשת וגו'.** מגיד שהבא על אשת אביו או על כלתו או השוכב את זכר משכבי אשה נסקלים הוא והם והנה הרצון באמרו תבל עשו בלילת זרע האב עם זרע הבן רוצה לומ' שישכבו שניהם עם אשה אחת:
@51 **ואיש אשר יקח את אשה ואת אמה.** אמר יקח להעיר שהאחת מהן אשתו והשנית חמותו או בת אשתו:
@51 **באש ישרפו אותו ואתהן.** ידוע כי אשר היא אשתו מהן אינה נשרפת כי לא עשת' עברה ואמר ואתהן הרצון בו הוא ואשר בעברה מהן אם האשה היתה בת אשתו או אמה אם היתה חמותו והוא מבואר כי השרפ' תהיה או אם שישרף הגוף באש בחבלי עצים או שישאר הגוף קיים כמו הענין בנדב ואביהוא כי גם זה יקרא שרפה אמר שם ואחיהם כל בית ישראל יבכו את השרפה אשר שרף השם. והנה יחוייב שנבאר הקלה שבאלו המיתות כמו שזכרנו במה שקדם ולזה תהיה זאת המיתה בשרפת נשמה וגוף קיים כאלו תאמר שיזרקו לתוך פיו מתכת חום נתך והוא יורד ושורף בני מעים וישאר הגוף קיים ולפי שאמ' אשה ואמה ואיננה כ"א לאחר מיתה הנה יתחייב מהמקומו' הכוללים שתהיינה שתיהן קיימות ואז יהיו נדונים בשרפה:
@52 **ואיש אשר יתן שכבתו בבהמה וגומר.** מגיד שהבהמה והרובע והנרבע כלם בסקילה שנאמר מות יומתו דמיהם בם והתועלת המגיע מהריגת הבהמה הוא שלא יזכרה עון הזה ויאמרו זאת היא שנסקל פלוני על ידה וזה כי ההמתה מכפרת לו העון הזה עם התשובה ולזה ראוי שלא יהיה בכאן מה שיביא לזכור העון ההוא עם התשובה כי בזה יתישב יותר בנפש האנשים שהחטא נמחל אחר קבול החוטא העונש המסודר עליו לפי הנימוס התוריי ועוד כי הזכירה הזאת תביא להרהר בעברה כל זמן שיראו הבהמה ההיא בזכרם שכבר שכב איש אותה או נרבעת אשה לה:
@54 **וראה את ערותה והיא תראה את ערותו.** ידוע כי הראיה תאמ' על שאר מיני ההרגש אמר ראה ריח בני וכל העם רואים את הקולות וכמו זה אמ' בזה המקום ראיה על חוש המשוש:
@54 **חסד הוא.** רוצה לומר שזאת הבעילה כבר תהיה ביניהן מחוזק האהבה לעשות חסד זה לזה ולזה יהיו נשמעים זה לזה תמיד אפילו בזולת אישות ומפני זה מנעה התורה זה כמו שזכרנו במה שקדם או יהיה חסד מענין בושת וחרפה כי הוא עזות מצח שישגל האדם שאר בשרו:
@54 **ונכרתו לעיני בני עמם.** אפשר שיהיה הרצון בזה שנפשם תכרת ותאבד ואפשר שיהיה הרצון שכבר יכרת מציאותם מישראל ויפסק רוצה לומר שלא יהיו להם בנים ולבניהם בנים וזה תמיד אבל יכלה זה המציאות באופן שלא ישאר להם יד ושם בישראל וזהו מה שאמר אחר זה תמורת שם הכרת ערירים ימותו ערירים יהיו רוצה לומר בלא בנים כמו ואנכי הולך ערירי ולמדתנו התורה בזה שהבא על אחותו או על הנדה או על אחות הוריו או על דודתו או על אשת אחיו נכרת הוא והן והנה הרצון באמרו נדה היא טמאה היא ומרוחקת להעיר על התעוב אשר בזה השגל:
@59 **ושמרתם את כל חקותי ואת כל משפטי ועשיתם אותם.** אחשוב שיהיה הרצון בשמירה זכירה ר"ל שנזכור אותם בלבנו ונעשה מעשנו על פי החקים והמשפטים ההם:
@59 **ולא תקיא אתכם הארץ וגו'.** מגיד שאם לא ישמרו ולא יעשו אלו החקים והמשפטים תקיא אותם הארץ ואמנם יהיה אם נסתבכו באלו העונות כלל ישראל או רבי' מהם וזה העונש הוא עונש נוסף על העונש שזכרה התורה בזה ליחידים החוטאים באלו החטאים כמו שביארנו בפרשה הקודמת:
@62 **והבדלתם בין הבהמה הטמאה לטהורה.** שב לזכור זה ובזה המקום להעמידנו על הכונה אשר בעבורה צותה התורה בזה כאלו ביאר כי הכונה בכל זה הוא שנהיה נכונים להקרב להשם יתע' בהשגתנו אותו כפי היכולת ולזה מנעה התורה ממנו אלו המשגלים כדי שלא נהיה נמשכים אל הנאות זה החוש כי זה ממה שימנע שלמות בעיון לטרדת המחשבה תמיד באי זה אופן ישיג שישגל האשה הפלונית וזה ממה שלא יצטרך אל ביאור והנה מנעה התורה ממנו אלו המאכלים מהמעבים החמר לכבותם אור השכל וזכותו בעיון כמו שזכרנו במה שקדם ולזה אמר בזה המקו' ואבדיל אתכם מן העמים להיות לי רוצה לומר כי מפני זה הבדילנו באלו החוקים והמשפטי' משאר מעמים כדי שנהיה להשם יתע':
@64 **ואיש או אשה כי יהיה בהם אוב או ידעוני וגו'.** מגיד שהן בסקילה וכבר התבאר שכל אלו העונשים שהם על ידי ב"ד יהיו כשיהיו שם עדים אומר על פי שנים עדים יומת המת וגו' וראוי שנדע שזה אמנם יהיה אחר ההתראה כי כשלא היתה שם התראה לא יודע אם הוא מזיד או שוגג וכבר ביארה התורה שהשוגג לא יתחייב מיתה במה שחייבה אותו קרבן בפרשת ויקרא והנה נשלם בכאן הביאור בזאת הפרשה:
